    question_object_id: str
    research_goal: str
    question: str
    falsification_condition: str
    proposal_artifact_sha256: str
    proposal_record_hash: str
    proposal_sha256: str
    outcome: ResearchGateOutcome
    verification_status: ScientificGateVerificationStatus
    goal_artifact_sha256: str
    goal_record_hash: str
    goal_sha256: str
    investigation_state_artifact_sha256: str
    investigation_state_record_hash: str
    investigation_state_sha256: str
    research_brief_artifact_sha256: str
    research_brief_record_hash: str
    research_brief_sha256: str
    selected_direction_id: str
    criteria_projection_sha256: str
    semantic_judgment_artifact_sha256: str | None
    semantic_judgment_record_hash: str | None
    semantic_judgment_structured_output_sha256: str | None
    evidence_artifact_hashes: tuple[str, ...]
    evidence_record_hashes: tuple[str, ...]

    def __post_init__(self) -> None:
        for name in (
            "receipt_id",
            "run_id",
            "gate_event_id",
            "object_id",
            "question_object_id",
            "selected_direction_id",
        ):
            object.__setattr__(self, name, _identifier(getattr(self, name), name))
        object.__setattr__(self, "ledger_path", _text(self.ledger_path, "ledger_path"))
        for name in ("research_goal", "question", "falsification_condition"):
            object.__setattr__(self, name, _text(getattr(self, name), name))
        object.__setattr__(
            self,
            "gate_event_hash",
            _sha256(self.gate_event_hash, "gate_event_hash"),
        )
        _positive_int(self.gate_event_index, "gate_event_index", allow_zero=True)
        outcome = _enum(self, "outcome", ResearchGateOutcome)
        if outcome is not ResearchGateOutcome.PROCEED:
            raise ScientificPromotionError(
                "research-question receipt cannot authorize a blocked gate"
            )
        _enum(self, "verification_status", ScientificGateVerificationStatus)
        for name in (
            "goal_artifact_sha256",
            "goal_record_hash",
            "goal_sha256",
            "investigation_state_artifact_sha256",
            "investigation_state_record_hash",
            "investigation_state_sha256",
            "research_brief_artifact_sha256",
            "research_brief_record_hash",
            "research_brief_sha256",
            "proposal_artifact_sha256",
            "proposal_record_hash",
            "proposal_sha256",
            "criteria_projection_sha256",
        ):
            object.__setattr__(self, name, _sha256(getattr(self, name), name))
        _validate_optional_semantic_receipt_binding(
            self,
            prefix="semantic_judgment_",
        )
        for name in ("evidence_artifact_hashes", "evidence_record_hashes"):
            values = _gate_hash_tuple(getattr(self, name), name)
            object.__setattr__(self, name, values)
        if self.evidence_artifact_hashes != tuple(
            sorted(self.evidence_artifact_hashes)
        ):
            raise ScientificDesignError(
                "evidence_artifact_hashes must be deterministically sorted"
            )
        if len(self.evidence_artifact_hashes) != len(self.evidence_record_hashes):
            raise ScientificDesignError(
                "research-question evidence metadata bindings are incomplete"
            )

    @property
    def source_artifact_hashes(self) -> tuple[str, ...]:
        return (self.proposal_artifact_sha256,)

    @property
    def scientific_gate_passed(self) -> bool:
        return (
            self.verification_status
            is ScientificGateVerificationStatus.SCIENTIFIC_EVIDENCE
            and self.outcome is ResearchGateOutcome.PROCEED
            and self.semantic_judgment_artifact_sha256 is not None
        )

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema_version": RESEARCH_QUESTION_GATE_RECEIPT_SCHEMA,
            "receipt_id": self.receipt_id,
            "run_id": self.run_id,
            "ledger_path": self.ledger_path,
            "gate_event_id": self.gate_event_id,
            "gate_event_hash": self.gate_event_hash,
            "gate_event_index": self.gate_event_index,
            "object_id": self.object_id,
            "question_object_id": self.question_object_id,
            "research_goal": self.research_goal,
            "question": self.question,
            "falsification_condition": self.falsification_condition,
            "proposal_artifact_sha256": self.proposal_artifact_sha256,
            "proposal_record_hash": self.proposal_record_hash,
            "proposal_sha256": self.proposal_sha256,
            "outcome": self.outcome.value,
            "verification_status": self.verification_status.value,
            "goal_artifact_sha256": self.goal_artifact_sha256,
            "goal_record_hash": self.goal_record_hash,
            "goal_sha256": self.goal_sha256,
            "investigation_state_artifact_sha256": (
                self.investigation_state_artifact_sha256
            ),
            "investigation_state_record_hash": self.investigation_state_record_hash,
            "investigation_state_sha256": self.investigation_state_sha256,
            "research_brief_artifact_sha256": self.research_brief_artifact_sha256,
            "research_brief_record_hash": self.research_brief_record_hash,
            "research_brief_sha256": self.research_brief_sha256,
            "selected_direction_id": self.selected_direction_id,
            "criteria_projection_sha256": self.criteria_projection_sha256,
            "semantic_judgment_artifact_sha256": (
                self.semantic_judgment_artifact_sha256
            ),
            "semantic_judgment_record_hash": self.semantic_judgment_record_hash,
            "semantic_judgment_structured_output_sha256": (
                self.semantic_judgment_structured_output_sha256
            ),
            "evidence_artifact_hashes": list(self.evidence_artifact_hashes),
            "evidence_record_hashes": list(self.evidence_record_hashes),
        }

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> ResearchQuestionGateReceipt:
        expected = set(cls.__dataclass_fields__) | {"schema_version"}
        _require_exact_keys(value, expected, "research-question gate receipt")
        if value["schema_version"] != RESEARCH_QUESTION_GATE_RECEIPT_SCHEMA:
            raise ScientificPromotionError(
                "unsupported research-question gate receipt schema"
            )
        try:
            arguments = {name: value[name] for name in cls.__dataclass_fields__}
            arguments["outcome"] = ResearchGateOutcome(arguments["outcome"])
            arguments["verification_status"] = ScientificGateVerificationStatus(
                arguments["verification_status"]
            )
            arguments["evidence_artifact_hashes"] = tuple(
                arguments["evidence_artifact_hashes"]
            )
            arguments["evidence_record_hashes"] = tuple(
                arguments["evidence_record_hashes"]
            )
            return cls(**arguments)
        except (KeyError, TypeError, ValueError) as exc:
            raise ScientificPromotionError(
                "research-question gate receipt is malformed"
            ) from exc


