# These are ordered predicates, not a set of status labels.  The new rule
# deliberately retains both NOT_SUPPORTED branches (margin equivalence and
# smaller harm), and both INCONCLUSIVE branches (minimum n and unresolved CI).
# Old policies retain their original five-predicate ordering and bytes.
BOUNDED_MEAN_HYPOTHESIS_OUTCOME_ORDER = (
    HypothesisStatus.INCONCLUSIVE,
    HypothesisStatus.FALSIFIED,
    HypothesisStatus.SUPPORTED,
    HypothesisStatus.NOT_SUPPORTED,
    HypothesisStatus.PARTIALLY_SUPPORTED,
    HypothesisStatus.NOT_SUPPORTED,
    HypothesisStatus.INCONCLUSIVE,
)


@dataclass(frozen=True, slots=True)
class HypothesisEvaluationPolicy:
    """Prospective exhaustive decision policy for one frozen hypothesis.

    The policy deliberately exposes thresholds, not executable expressions or
    prose parsing.  Each explicit rule owns a closed ordered partition.  The
    historical rule consumes ordinary facts; the new bounded-mean rule only
    consumes freshly recomputed bounded-mean output, never rounded generic
    facts or a sign-test p-value substituted for a mean test.
    """

    policy_id: str
    hypothesis_id: str
    metric_id: str
    meaningful_effect: float
    falsification_effect: float
    alpha: float
    minimum_sample_size: int
    rule_id: str = HYPOTHESIS_EVALUATION_POLICY_RULE_ID
    outcome_order: tuple[HypothesisStatus, ...] = (
        HypothesisStatus.INCONCLUSIVE,
        HypothesisStatus.FALSIFIED,
        HypothesisStatus.SUPPORTED,
        HypothesisStatus.PARTIALLY_SUPPORTED,
        HypothesisStatus.NOT_SUPPORTED,
    )

    def __post_init__(self) -> None:
        for name in ("policy_id", "hypothesis_id", "metric_id"):
            object.__setattr__(self, name, _identifier(getattr(self, name), name))
        for name in ("meaningful_effect", "falsification_effect"):
            value = _finite(getattr(self, name), name)
            if value <= 0:
                raise ScientificDesignError(f"{name} must be positive")
            object.__setattr__(self, name, value)
        object.__setattr__(self, "alpha", _probability(self.alpha, "alpha"))
        _positive_int(self.minimum_sample_size, "minimum_sample_size")
        if self.rule_id not in {
            HYPOTHESIS_EVALUATION_POLICY_RULE_ID,
            BOUNDED_MEAN_DECISION_RULE_ID,
        }:
            raise ScientificDesignError("unsupported hypothesis evaluation rule")
        expected_order = (
            HypothesisStatus.INCONCLUSIVE,
            HypothesisStatus.FALSIFIED,
            HypothesisStatus.SUPPORTED,
            HypothesisStatus.PARTIALLY_SUPPORTED,
            HypothesisStatus.NOT_SUPPORTED,
        )
        if self.rule_id == BOUNDED_MEAN_DECISION_RULE_ID:
            expected_order = BOUNDED_MEAN_HYPOTHESIS_OUTCOME_ORDER
            if (
                type(self.minimum_sample_size) is not int
                or self.alpha >= 1
                or self.meaningful_effect > 1
                or self.falsification_effect > 1
                or self.minimum_sample_size > MAX_BOUNDED_MEAN_UNITS
            ):
                raise ScientificDesignError(
                    "bounded-mean policy exceeds its alpha, margin or unit scope"
                )
            if type(self.outcome_order) is not tuple or any(
                type(status) is not HypothesisStatus for status in self.outcome_order
            ):
                raise ScientificDesignError(
                    "bounded-mean policy requires an exact typed outcome tuple"
                )
        if self.outcome_order != expected_order:
            raise ScientificDesignError(
                "hypothesis evaluation outcomes must use the exhaustive disjoint order"
            )

    @property
    def sha256(self) -> str:
        return _canonical_hash(self)


@dataclass(frozen=True, slots=True)
class HypothesisEvaluationFacts:
    """Exact statistic projection consumed by the frozen decision policy."""

    improvement_effect: float
    confidence_low: float
    confidence_high: float
    adjusted_p_value: float | None
    sample_size: int

    def __post_init__(self) -> None:
        for name in ("improvement_effect", "confidence_low", "confidence_high"):
            object.__setattr__(self, name, _finite(getattr(self, name), name))
        if not self.confidence_low <= self.improvement_effect <= self.confidence_high:
            raise ScientificDesignError(
                "hypothesis evaluation effect must lie inside its confidence interval"
            )
        if self.adjusted_p_value is not None:
            object.__setattr__(
                self,
                "adjusted_p_value",
                _probability(
                    self.adjusted_p_value,
                    "adjusted_p_value",
                    allow_zero=True,
                ),
            )
        _positive_int(self.sample_size, "sample_size")


def evaluate_hypothesis_policy(
    policy: HypothesisEvaluationPolicy,
    facts: HypothesisEvaluationFacts,
) -> HypothesisStatus:
    """Derive exactly one status without consulting hypothesis prose.

    Order is material: underpowered, absent-p, or substantively two-sided
    evidence is inconclusive; decisive opposite-direction evidence is
    falsification; decisive meaningful positive evidence is support; smaller decisive
    positive effects are partial support; every remaining valid observation is
    not supported.  These predicates are mutually exclusive by construction.
    """

    if not isinstance(policy, HypothesisEvaluationPolicy) or not isinstance(
        facts, HypothesisEvaluationFacts
    ):
        raise ScientificDesignError(
            "hypothesis evaluation requires a typed frozen policy and facts"
        )
    if policy.rule_id != HYPOTHESIS_EVALUATION_POLICY_RULE_ID:
        raise ScientificDesignError(
            "bounded-mean policy requires exact bounded-mean output, not generic facts"
        )
    p_value = facts.adjusted_p_value
    if (
        facts.sample_size < policy.minimum_sample_size
        or p_value is None
        or (
            facts.confidence_low < -policy.falsification_effect
            and facts.confidence_high > policy.meaningful_effect
        )
    ):
        return HypothesisStatus.INCONCLUSIVE
    if (
        p_value <= policy.alpha
        and facts.confidence_high <= -policy.falsification_effect
    ):
        return HypothesisStatus.FALSIFIED
    if (
        p_value <= policy.alpha
        and facts.confidence_low >= policy.meaningful_effect
    ):
        return HypothesisStatus.SUPPORTED
    if (
        p_value <= policy.alpha
        and facts.improvement_effect > 0
        and facts.confidence_low > 0
    ):
        return HypothesisStatus.PARTIALLY_SUPPORTED
    return HypothesisStatus.NOT_SUPPORTED


def _replay_bounded_mean_policy_result(
    policy: HypothesisEvaluationPolicy,
    result: BoundedMeanInferenceResult,
) -> BoundedMeanInferenceResult:
    """Recompute numerical inputs only; this does not establish source authority."""

    if (
        type(policy) is not HypothesisEvaluationPolicy
        or type(result) is not BoundedMeanInferenceResult
        or type(policy.rule_id) is not str
    ):
        raise ScientificDesignError(
            "bounded-mean policy requires an exact policy and numerical result"
        )
    owned_policy = replace(policy)
    if owned_policy.rule_id != BOUNDED_MEAN_DECISION_RULE_ID:
        raise ScientificDesignError("bounded-mean output requires its prospective rule")
    recomputed = replace(result)
    if result != recomputed:
        raise ScientificDesignError("bounded-mean derived output differs from recomputation")
    plan = recomputed.plan
    if (
        plan.alpha != owned_policy.alpha
        or plan.benefit_margin != owned_policy.meaningful_effect
        or plan.harm_margin != owned_policy.falsification_effect
        or plan.minimum_unit_count != owned_policy.minimum_sample_size
    ):
        raise ScientificDesignError(
            "bounded-mean numerical plan differs from the prospective hypothesis policy"
        )
    return recomputed


def _bounded_mean_hypothesis_status(decision: BoundedMeanDecision) -> HypothesisStatus:
    return {
        BoundedMeanDecision.INCONCLUSIVE: HypothesisStatus.INCONCLUSIVE,
        BoundedMeanDecision.FALSIFIED: HypothesisStatus.FALSIFIED,
        BoundedMeanDecision.SUPPORTED: HypothesisStatus.SUPPORTED,
        BoundedMeanDecision.EQUIVALENT_WITHIN_MARGINS: HypothesisStatus.NOT_SUPPORTED,
        BoundedMeanDecision.PARTIALLY_SUPPORTED: HypothesisStatus.PARTIALLY_SUPPORTED,
        BoundedMeanDecision.NEGATIVE: HypothesisStatus.NOT_SUPPORTED,
    }[decision]


def evaluate_bounded_mean_hypothesis_policy(
    policy: HypothesisEvaluationPolicy,
    result: BoundedMeanInferenceResult,
) -> HypothesisStatus:
    """Map exact interval decisions without minting scientific authority.

    Source consumers must separately replay the frozen contract, unit/seed
    projection, statistical-use review, execution and confirmation.  Possession
    of these caller-reproducible DTOs is not evidence of any of those properties.
    """

    current = _replay_bounded_mean_policy_result(policy, result)
    return _bounded_mean_hypothesis_status(current.decision)


@dataclass(frozen=True, slots=True)
class EvaluationContract:
    contract_id: str
    version: int
    research_brief_sha256: str
    novelty_register: NoveltyRegister
    hypothesis_register: HypothesisRegister
    dataset: DatasetContract
    primary_metric: MetricSpec
    secondary_metrics: tuple[MetricSpec, ...]
    baseline_registry: BaselineRegistry
    candidate_conditions: ComparisonConditions
    seed_reporting: SeedReportingPlan
    compute_budget: ComputeBudget
    statistical_plan: StatisticalPlan
    robustness_tests: tuple[str, ...]
    ablations: tuple[AblationSpec, ...]
    stopping_criteria: tuple[str, ...]
    success_criteria: tuple[str, ...]
    failure_criteria: tuple[str, ...]
    separation: ExecutionSeparation
    proxy_inferences: tuple[ProxyInferenceContract, ...]
    frozen_at: str
    frozen_by: str
    results_seen_at_freeze: bool = False
    hypothesis_evaluation_policies: tuple[HypothesisEvaluationPolicy, ...] = ()
    scientific_execution_admissibility_policy: (
        ScientificExecutionAdmissibilityPolicy | None
    ) = None

    def __post_init__(self) -> None:
        object.__setattr__(self, "contract_id", _identifier(self.contract_id, "contract_id"))
        _positive_int(self.version, "version")
        object.__setattr__(
            self,
            "research_brief_sha256",
            _sha256(self.research_brief_sha256, "research_brief_sha256"),
        )
        typed = (
            (self.novelty_register, NoveltyRegister, "novelty_register"),
            (self.hypothesis_register, HypothesisRegister, "hypothesis_register"),
            (self.dataset, DatasetContract, "dataset"),
            (self.primary_metric, MetricSpec, "primary_metric"),
            (self.baseline_registry, BaselineRegistry, "baseline_registry"),
            (self.candidate_conditions, ComparisonConditions, "candidate_conditions"),
            (self.seed_reporting, SeedReportingPlan, "seed_reporting"),
            (self.compute_budget, ComputeBudget, "compute_budget"),
            (self.statistical_plan, StatisticalPlan, "statistical_plan"),
            (self.separation, ExecutionSeparation, "separation"),
        )
        for value, expected, name in typed:
            if not isinstance(value, expected):
                raise ScientificDesignError(f"{name} must be {expected.__name__}")
        _tuple(self.secondary_metrics, "secondary_metrics", allow_empty=True)
        if not all(isinstance(metric, MetricSpec) for metric in self.secondary_metrics):
            raise ScientificDesignError("secondary_metrics contains an invalid metric")
        metric_ids = (self.primary_metric.metric_id,) + tuple(
            metric.metric_id for metric in self.secondary_metrics
        )
        if len(set(metric_ids)) != len(metric_ids):
            raise ScientificDesignError("metric IDs must be unique")
        for name in (
            "robustness_tests",
            "stopping_criteria",
            "success_criteria",
            "failure_criteria",
        ):
            object.__setattr__(self, name, _strings(getattr(self, name), name))
        _tuple(self.ablations, "ablations", allow_empty=True)
        if not all(isinstance(item, AblationSpec) for item in self.ablations):
            raise ScientificDesignError("ablations contains an invalid value")
        ablation_ids = tuple(item.ablation_id for item in self.ablations)
        if len(set(ablation_ids)) != len(ablation_ids):
            raise ScientificDesignError("ablation IDs must be unique")
        hypothesis_ids = {item.hypothesis_id for item in self.hypothesis_register.hypotheses}
        if any(item.hypothesis_id not in hypothesis_ids for item in self.ablations):
            raise ScientificDesignError("ablation references an unknown hypothesis")
        _tuple(self.proxy_inferences, "proxy_inferences", allow_empty=True)
        if not all(isinstance(item, ProxyInferenceContract) for item in self.proxy_inferences):
            raise ScientificDesignError("proxy_inferences contains an invalid value")
        for inference in self.proxy_inferences:
            if inference.proxy_metric_id not in metric_ids or inference.end_to_end_metric_id not in metric_ids:
                raise ScientificDesignError("proxy inference references an unknown metric")
            proxy = self.metric(inference.proxy_metric_id)
            end_to_end = self.metric(inference.end_to_end_metric_id)
            if proxy.scope is not MetricScope.PROXY or end_to_end.scope is not MetricScope.END_TO_END:
                raise ScientificDesignError("proxy inference must bind PROXY to END_TO_END metrics")
        primary = self.hypothesis_register.primary
        if primary.timing is not HypothesisTiming.PRE_SPECIFIED:
            raise ScientificDesignError("confirmatory primary hypothesis must be pre-specified")
        if primary.status is not HypothesisStatus.UNTESTED:
            raise ScientificDesignError("evaluation contract must freeze before primary results")
        for novelty in self.novelty_register.entries:
            self.novelty_register.require_clearance(novelty.contribution_id)
        if self.candidate_conditions.metric_id != self.primary_metric.metric_id:
            raise ScientificDesignError("candidate comparison metric differs from primary metric")
        if self.candidate_conditions.metric_unit is not self.primary_metric.unit:
            raise ScientificDesignError("candidate comparison unit differs from primary metric")
        if self.compute_budget.max_runs < len(self.seed_reporting.seeds):
            raise ScientificDesignError("compute budget cannot cover the frozen seed set")
        if self.candidate_conditions.tuning_trials > self.compute_budget.max_tuning_trials:
            raise ScientificDesignError("candidate tuning policy exceeds the compute budget")
        for baseline in self.baseline_registry.entries:
            if baseline.conditions.tuning_trials > self.compute_budget.max_tuning_trials:
                raise ScientificDesignError(
                    f"baseline tuning policy exceeds the compute budget: {baseline.baseline_id}"
                )
            if (
                baseline.status
                not in {BaselineStatus.CONTEXT_ONLY, BaselineStatus.INCOMPATIBLE}
                and baseline.exclusion is None
            ):
                report = compare_fairness(
                    self.candidate_conditions,
                    baseline.baseline_id,
                    baseline.conditions,
                )
                if not report.equivalent:
                    raise ScientificDesignError(
                        f"frozen baseline comparison is unfair for {baseline.baseline_id}: "
                        + ", ".join(report.mismatches)
                    )
        if self.separation.confirmatory_max_runs > self.compute_budget.max_runs:
            raise ScientificDesignError("confirmatory allocation exceeds compute budget")
        object.__setattr__(self, "frozen_at", _text(self.frozen_at, "frozen_at"))
        object.__setattr__(self, "frozen_by", _identifier(self.frozen_by, "frozen_by"))
        if not isinstance(self.results_seen_at_freeze, bool):
            raise ScientificDesignError("results_seen_at_freeze must be boolean")
        if self.results_seen_at_freeze:
            raise ScientificDesignError("evaluation contract must be frozen before results are seen")
        policies = self.hypothesis_evaluation_policies
        _tuple(
            policies,
            "hypothesis_evaluation_policies",
            allow_empty=True,
            maximum=MAX_HYPOTHESES,
        )
        if not all(isinstance(item, HypothesisEvaluationPolicy) for item in policies):
            raise ScientificDesignError(
                "hypothesis_evaluation_policies contains an invalid value"
            )
        if policies:
            policy_hypothesis_ids = tuple(item.hypothesis_id for item in policies)
            if len(set(policy_hypothesis_ids)) != len(policy_hypothesis_ids):
                raise ScientificDesignError(
                    "hypothesis evaluation policy IDs must be unique by hypothesis"
                )
            if set(policy_hypothesis_ids) != hypothesis_ids:
                raise ScientificDesignError(
                    "v2 evaluation contract requires one policy for every hypothesis"
                )
            if any(item.metric_id not in metric_ids for item in policies):
                raise ScientificDesignError(
                    "hypothesis evaluation policy references an unknown metric"
                )
            policy_ids = tuple(item.policy_id for item in policies)
            if len(set(policy_ids)) != len(policy_ids):
                raise ScientificDesignError(
                    "hypothesis evaluation policy IDs must be unique"
                )
        admissibility_policy = self.scientific_execution_admissibility_policy
        if admissibility_policy is not None:
            if not isinstance(
                admissibility_policy,
                ScientificExecutionAdmissibilityPolicy,
            ):
                raise ScientificDesignError(
                    "scientific execution admissibility policy is invalid"
                )
            if not policies:
                raise ScientificDesignError(
                    "v3 evaluation contract requires exhaustive hypothesis policies"
                )
            if self.stopping_criteria != FIXED_COMPLETE_GENERIC_ML_STOPPING_CRITERIA:
                raise ScientificDesignError(
                    "v3 evaluation contract stopping display differs from its closed policy"
                )

    def metric(self, metric_id: str) -> MetricSpec:
        _identifier(metric_id, "metric_id")
        for metric in (self.primary_metric,) + self.secondary_metrics:
            if metric.metric_id == metric_id:
                return metric
        raise ScientificDesignError(f"unknown metric {metric_id!r}")

    def hypothesis_evaluation_policy(
        self,
        hypothesis_id: str,
    ) -> HypothesisEvaluationPolicy:
        _identifier(hypothesis_id, "hypothesis_id")
        for policy in self.hypothesis_evaluation_policies:
            if policy.hypothesis_id == hypothesis_id:
                return policy
        raise ScientificPromotionError(
            "frozen evaluation contract has no prospective hypothesis policy"
        )

    @property
    def sha256(self) -> str:
        return _canonical_hash(_evaluation_contract_value(self))


_EVALUATION_CONTRACT_V2_FIELD = "hypothesis_evaluation_policies"
_EVALUATION_CONTRACT_V3_FIELD = "scientific_execution_admissibility_policy"


def _evaluation_contract_schema(contract: EvaluationContract) -> str:
    if contract.scientific_execution_admissibility_policy is not None:
        return CHECKED_SUPERIORITY_CONTRACT_SCHEMA_V3
    return (
        CHECKED_SUPERIORITY_CONTRACT_SCHEMA_V2
        if contract.hypothesis_evaluation_policies
        else CHECKED_SUPERIORITY_CONTRACT_SCHEMA
    )


def _evaluation_contract_artifact_schema(contract: EvaluationContract) -> str:
    schema = _evaluation_contract_schema(contract)
    return {
        CHECKED_SUPERIORITY_CONTRACT_SCHEMA: EVALUATION_CONTRACT_ARTIFACT_SCHEMA_V1,
        CHECKED_SUPERIORITY_CONTRACT_SCHEMA_V2: EVALUATION_CONTRACT_ARTIFACT_SCHEMA_V2,
        CHECKED_SUPERIORITY_CONTRACT_SCHEMA_V3: EVALUATION_CONTRACT_ARTIFACT_SCHEMA_V3,
    }[schema]


def _evaluation_contract_schema_pair_is_valid(
    payload_schema: object,
    artifact_schema: object,
) -> bool:
    return (payload_schema, artifact_schema) in {
        (
            CHECKED_SUPERIORITY_CONTRACT_SCHEMA,
            EVALUATION_CONTRACT_ARTIFACT_SCHEMA_V1,
        ),
        (
            CHECKED_SUPERIORITY_CONTRACT_SCHEMA_V2,
            EVALUATION_CONTRACT_ARTIFACT_SCHEMA_V2,
        ),
        (
            CHECKED_SUPERIORITY_CONTRACT_SCHEMA_V3,
            EVALUATION_CONTRACT_ARTIFACT_SCHEMA_V3,
        ),
    }


def _evaluation_contract_value(contract: EvaluationContract) -> Mapping[str, Any]:
    """Return the versioned payload while preserving historical v1 bytes."""

    if not isinstance(contract, EvaluationContract):
        raise ScientificDesignError("contract must be EvaluationContract")
    try:
        value = safe_json_loads(canonical_json_bytes(contract))
    except (UnsafeSerializationError, TypeError, ValueError) as exc:
        raise ScientificDesignError(
            "evaluation contract is not canonically serializable"
        ) from exc
    if not isinstance(value, Mapping):  # pragma: no cover - dataclass serialization
        raise ScientificDesignError("evaluation contract payload is malformed")
    result = dict(value)
    if not contract.hypothesis_evaluation_policies:
        result.pop(_EVALUATION_CONTRACT_V2_FIELD, None)
    if contract.scientific_execution_admissibility_policy is None:
        result.pop(_EVALUATION_CONTRACT_V3_FIELD, None)
    else:
        result[_EVALUATION_CONTRACT_V3_FIELD] = (
            contract.scientific_execution_admissibility_policy.to_dict()
        )
    return result


def _evaluation_contract_payload_fields(schema: str) -> set[str]:
    current = {field.name for field in fields(EvaluationContract)}
    if schema == CHECKED_SUPERIORITY_CONTRACT_SCHEMA:
        return current - {
            _EVALUATION_CONTRACT_V2_FIELD,
            _EVALUATION_CONTRACT_V3_FIELD,
        }
    if schema == CHECKED_SUPERIORITY_CONTRACT_SCHEMA_V2:
        return current - {_EVALUATION_CONTRACT_V3_FIELD}
    if schema == CHECKED_SUPERIORITY_CONTRACT_SCHEMA_V3:
        return current
    raise ScientificPromotionError("unsupported checked evaluation-contract schema")


def _normalized_evaluation_contract_payload(
    schema: str,
    value: Any,
) -> dict[str, Any]:
    """Normalize the sole backward-safe v1 dataclass serialization variant.

    Historical v1 artifacts omit the newly appended field.  Some callers use
    generic dataclass serialization and therefore emit it as an explicit empty
    list after upgrading this library.  Both forms mean exactly v1; a nonempty
    field, any other extra key, or v2 omission remains invalid.
    """

    if not isinstance(value, Mapping):
        raise ScientificPromotionError(
            "evaluation contract payload must be an object"
        )
    normalized = dict(value)
    if schema == CHECKED_SUPERIORITY_CONTRACT_SCHEMA:
        if _EVALUATION_CONTRACT_V2_FIELD in normalized:
            if normalized[_EVALUATION_CONTRACT_V2_FIELD] != []:
                raise ScientificPromotionError(
                    "v1 evaluation contract cannot contain hypothesis policies"
                )
            normalized.pop(_EVALUATION_CONTRACT_V2_FIELD)
    if schema in {
        CHECKED_SUPERIORITY_CONTRACT_SCHEMA,
        CHECKED_SUPERIORITY_CONTRACT_SCHEMA_V2,
    } and _EVALUATION_CONTRACT_V3_FIELD in normalized:
        if normalized[_EVALUATION_CONTRACT_V3_FIELD] is not None:
            raise ScientificPromotionError(
                "legacy evaluation contract cannot contain an admissibility policy"
            )
        normalized.pop(_EVALUATION_CONTRACT_V3_FIELD)
    if set(normalized) != _evaluation_contract_payload_fields(schema):
        raise ScientificPromotionError(
            "evaluation contract schema is incomplete or contains unknown fields"
        )
    return normalized


_CONTRACT_CONTROLLER_FIELDS = frozenset(
    {"contract_id", "version", "frozen_at", "frozen_by", "results_seen_at_freeze"}
)
_CONTRACT_AMENDABLE_FIELDS = frozenset(
    field.name for field in fields(EvaluationContract)
) - _CONTRACT_CONTROLLER_FIELDS


@dataclass(frozen=True, slots=True)
class EvaluationContractAmendment:
    """Append-only explanation and lineage binding for a new contract version."""

    amendment_id: str
    parent_contract_sha256: str
    contract_id: str
    from_version: int
    to_version: int
    recorded_at: str
    author_id: str
    reason: str
    affected_experiment_ids: tuple[str, ...]
    changed_fields: tuple[str, ...]
    results_already_seen: bool
    requires_new_confirmatory_reserve: bool

    def __post_init__(self) -> None:
        for name in ("amendment_id", "contract_id", "author_id"):
            object.__setattr__(self, name, _identifier(getattr(self, name), name))
        object.__setattr__(
            self,
            "parent_contract_sha256",
            _sha256(self.parent_contract_sha256, "parent_contract_sha256"),
        )
        _positive_int(self.from_version, "from_version")
        _positive_int(self.to_version, "to_version")
        if self.to_version != self.from_version + 1:
            raise ScientificDesignError("contract amendment must advance exactly one version")
        object.__setattr__(self, "recorded_at", _text(self.recorded_at, "recorded_at"))
        object.__setattr__(self, "reason", _text(self.reason, "reason"))
        object.__setattr__(
            self,
            "affected_experiment_ids",
            _identifiers(self.affected_experiment_ids, "affected_experiment_ids"),
        )
        changed = _strings(self.changed_fields, "changed_fields")
        unknown = set(changed) - _CONTRACT_AMENDABLE_FIELDS
        if unknown:
            raise ScientificDesignError(
                "contract amendment names non-amendable fields: "
                + ", ".join(sorted(unknown))
            )
        object.__setattr__(self, "changed_fields", changed)
        for name in ("results_already_seen", "requires_new_confirmatory_reserve"):
            if not isinstance(getattr(self, name), bool):
                raise ScientificDesignError(f"{name} must be boolean")
        if self.results_already_seen and not self.requires_new_confirmatory_reserve:
            raise ScientificDesignError(
                "post-result amendment requires a fresh confirmatory reserve"
            )

    @property
    def sha256(self) -> str:
        return _canonical_hash(self)


def record_evaluation_contract_amendment(
    contract: EvaluationContract,
    *,
    amendment_id: str,
    recorded_at: str,
    author_id: str,
    reason: str,
    affected_experiment_ids: tuple[str, ...],
    changed_fields: tuple[str, ...],
    results_already_seen: bool,
    requires_new_confirmatory_reserve: bool,
) -> EvaluationContractAmendment:
    if not isinstance(contract, EvaluationContract):
        raise ScientificDesignError("contract must be EvaluationContract")
    return EvaluationContractAmendment(
        amendment_id=amendment_id,
        parent_contract_sha256=contract.sha256,
        contract_id=contract.contract_id,
        from_version=contract.version,
        to_version=contract.version + 1,
        recorded_at=recorded_at,
        author_id=author_id,
        reason=reason,
        affected_experiment_ids=affected_experiment_ids,
        changed_fields=changed_fields,
        results_already_seen=results_already_seen,
        requires_new_confirmatory_reserve=requires_new_confirmatory_reserve,
    )


def validate_amended_evaluation_contract(
    parent: EvaluationContract,
    child: EvaluationContract,
    amendment: EvaluationContractAmendment,
) -> None:
    """Validate lineage without mutating or retroactively governing the parent."""

    if not isinstance(parent, EvaluationContract) or not isinstance(child, EvaluationContract):
        raise ScientificDesignError("parent and child must be EvaluationContract")
    if not isinstance(amendment, EvaluationContractAmendment):
        raise ScientificDesignError("amendment must be EvaluationContractAmendment")
    if amendment.parent_contract_sha256 != parent.sha256:
        raise ScientificPromotionError("amendment does not bind the parent contract")
    if parent.contract_id != child.contract_id or amendment.contract_id != parent.contract_id:
        raise ScientificPromotionError("contract identity cannot change through amendment")
    if child.version != parent.version + 1 or amendment.to_version != child.version:
        raise ScientificPromotionError("child is not the exact next contract version")
    changed = tuple(
        field_name
        for field_name in sorted(_CONTRACT_AMENDABLE_FIELDS)
        if getattr(parent, field_name) != getattr(child, field_name)
    )
    if changed != tuple(sorted(amendment.changed_fields)):
        raise ScientificPromotionError(
            "amendment changed_fields do not exactly describe the new contract"
        )
    if child.separation.protected_resource_id == parent.separation.protected_resource_id:
        raise ScientificPromotionError(
            "contract amendment cannot reuse protected validity authority without a checked pre-result timeline"
        )


class ExperimentStage(StrEnum):
    EXPLORATORY = "EXPLORATORY"
    CONFIRMATORY = "CONFIRMATORY"


@dataclass(frozen=True, slots=True)
class ExperimentPlan:
    experiment_id: str
    hypothesis_id: str
    stage: ExperimentStage
    contract_sha256: str
    dataset_split_id: str
    seed: int
    evaluator_id: str
    uses_protected_resource: bool
    results_seen_before_plan: bool
    ablation_id: str | None = None

    def __post_init__(self) -> None:
        for name in ("experiment_id", "hypothesis_id", "dataset_split_id", "evaluator_id"):
            object.__setattr__(self, name, _identifier(getattr(self, name), name))
        _enum(self, "stage", ExperimentStage)
        object.__setattr__(
            self,
            "contract_sha256",
            _sha256(self.contract_sha256, "contract_sha256"),
        )
        if isinstance(self.seed, bool) or not isinstance(self.seed, int) or self.seed < 0:
            raise ScientificDesignError("seed must be a non-negative integer")
        for name in ("uses_protected_resource", "results_seen_before_plan"):
            if not isinstance(getattr(self, name), bool):
                raise ScientificDesignError(f"{name} must be boolean")
        if self.ablation_id is not None:
            object.__setattr__(self, "ablation_id", _identifier(self.ablation_id, "ablation_id"))

    @property
    def sha256(self) -> str:
        return _canonical_hash(self)

    def to_dict(self) -> dict[str, Any]:
        return {
            "experiment_id": self.experiment_id,
            "hypothesis_id": self.hypothesis_id,
            "stage": self.stage.value,
            "contract_sha256": self.contract_sha256,
            "dataset_split_id": self.dataset_split_id,
            "seed": self.seed,
            "evaluator_id": self.evaluator_id,
            "uses_protected_resource": self.uses_protected_resource,
            "results_seen_before_plan": self.results_seen_before_plan,
            "ablation_id": self.ablation_id,
        }

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> ExperimentPlan:
        expected = {
            "experiment_id",
            "hypothesis_id",
            "stage",
            "contract_sha256",
            "dataset_split_id",
            "seed",
            "evaluator_id",
            "uses_protected_resource",
            "results_seen_before_plan",
            "ablation_id",
        }
        if not isinstance(value, Mapping) or set(value) != expected:
            raise ScientificPromotionError(
                "frozen experiment-plan schema is incomplete or contains unknown fields"
            )
        try:
            return cls(
                experiment_id=value["experiment_id"],
                hypothesis_id=value["hypothesis_id"],
                stage=ExperimentStage(value["stage"]),
                contract_sha256=value["contract_sha256"],
                dataset_split_id=value["dataset_split_id"],
                seed=value["seed"],
                evaluator_id=value["evaluator_id"],
                uses_protected_resource=value["uses_protected_resource"],
                results_seen_before_plan=value["results_seen_before_plan"],
                ablation_id=value["ablation_id"],
            )
        except (KeyError, TypeError, ValueError) as exc:
            raise ScientificPromotionError("frozen experiment plan is malformed") from exc


def _validate_experiment_plan_structure(
    contract: EvaluationContract,
    plan: ExperimentPlan,
) -> None:
    if not isinstance(contract, EvaluationContract) or not isinstance(plan, ExperimentPlan):
        raise ScientificDesignError("experiment admission requires typed contract and plan")
    if plan.contract_sha256 != contract.sha256:
        raise ScientificPromotionError("experiment is not bound to the frozen evaluation contract")
    hypothesis = contract.hypothesis_register.hypothesis(plan.hypothesis_id)
    if plan.experiment_id != hypothesis.planned_experiment:
        raise ScientificPromotionError(
            "experiment identity differs from the hypothesis's frozen planned experiment"
        )
    if plan.seed not in contract.seed_reporting.seeds:
        raise ScientificPromotionError("experiment seed is outside the frozen seed policy")
    if plan.evaluator_id != contract.candidate_conditions.evaluator:
        raise ScientificPromotionError("experiment evaluator differs from the frozen evaluator")
    if plan.ablation_id is not None:
        ablations = {
            item.ablation_id: item
            for item in contract.ablations
        }
        if plan.ablation_id not in ablations:
            raise ScientificPromotionError("experiment references an unregistered ablation")
        if ablations[plan.ablation_id].hypothesis_id != plan.hypothesis_id:
            raise ScientificPromotionError(
                "experiment ablation belongs to a different hypothesis"
            )
    if plan.stage is ExperimentStage.EXPLORATORY:
        if plan.uses_protected_resource:
            raise ScientificPromotionError("exploration cannot consume protected validity resources")
        if plan.dataset_split_id not in contract.dataset.exploratory_split_ids:
            raise ScientificPromotionError(
                "exploration must use an exact frozen exploratory split identity"
            )
    else:
        if hypothesis.hypothesis_id != contract.hypothesis_register.primary.hypothesis_id:
            raise ScientificPromotionError("confirmatory work must test the frozen primary hypothesis")
        if hypothesis.timing is not HypothesisTiming.PRE_SPECIFIED:
            raise ScientificPromotionError("POST_HOC hypothesis cannot enter this confirmation")
        if not plan.uses_protected_resource:
            raise ScientificPromotionError("confirmatory plan must declare protected-resource use")
        if plan.dataset_split_id != contract.dataset.confirmatory_split_id:
            raise ScientificPromotionError("confirmatory plan must use the frozen confirmatory split")
        # ``results_seen_before_plan`` is descriptive only.  Authoritative
        # confirmatory admission is established by the registry/ledger design
        # freeze sequence, never by this caller-supplied value.


def admit_experiment(contract: EvaluationContract, plan: ExperimentPlan) -> None:
    """Validate structure; protected confirmation requires checked timeline admission."""

    _validate_experiment_plan_structure(contract, plan)
    if plan.stage is ExperimentStage.CONFIRMATORY:
        raise ScientificPromotionError(
            "confirmatory admission requires a registry/ledger design-freeze checkpoint"
        )


class ExploitationSignalKind(StrEnum):
    EVALUATOR_ACCESS = "EVALUATOR_ACCESS"
    HIDDEN_TEST_QUERY = "HIDDEN_TEST_QUERY"
    SCORE_ONLY_ADAPTATION = "SCORE_ONLY_ADAPTATION"
    METRIC_PARSER_MANIPULATION = "METRIC_PARSER_MANIPULATION"
    OUTPUT_FORMAT_GAMING = "OUTPUT_FORMAT_GAMING"
    BENCHMARK_STATE_MUTATION = "BENCHMARK_STATE_MUTATION"
    LEAKAGE = "LEAKAGE"


@dataclass(frozen=True, slots=True)
class EvaluatorExploitationSignal:
    kind: ExploitationSignalKind
    detail: str
    evidence_id: str
    blocking: bool = True

    def __post_init__(self) -> None:
        _enum(self, "kind", ExploitationSignalKind)
        object.__setattr__(self, "detail", _text(self.detail, "signal detail"))
        object.__setattr__(self, "evidence_id", _identifier(self.evidence_id, "evidence_id"))
        if not isinstance(self.blocking, bool):
            raise ScientificDesignError("blocking must be boolean")


@dataclass(frozen=True, slots=True)
class EvaluatorAssessment:
    evaluator_id: str
    evaluator_version: str
    signals: tuple[EvaluatorExploitationSignal, ...]
    passed: bool

    def __post_init__(self) -> None:
        object.__setattr__(self, "evaluator_id", _identifier(self.evaluator_id, "evaluator_id"))
        object.__setattr__(
            self,
            "evaluator_version",
            _text(self.evaluator_version, "evaluator_version"),
        )
        _tuple(self.signals, "evaluator signals", allow_empty=True)
        if not all(isinstance(signal, EvaluatorExploitationSignal) for signal in self.signals):
            raise ScientificDesignError("evaluator signals contains an invalid value")
        if not isinstance(self.passed, bool):
            raise ScientificDesignError("passed must be boolean")
        if self.passed and any(signal.blocking for signal in self.signals):
            raise ScientificDesignError("evaluator cannot pass with a blocking exploitation signal")


def require_evaluator_integrity(assessment: EvaluatorAssessment) -> None:
    if not isinstance(assessment, EvaluatorAssessment):
        raise ScientificDesignError("assessment must be EvaluatorAssessment")
    if not assessment.passed or assessment.signals:
        kinds = ", ".join(signal.kind.value for signal in assessment.signals) or "assessment failed"
        raise ScientificPromotionError(f"evaluator integrity is not established: {kinds}")


def validate_ablation_results(
    contract: EvaluationContract,
    results: tuple[AblationResult, ...],
) -> None:
    if not isinstance(contract, EvaluationContract):
        raise ScientificDesignError("contract must be EvaluationContract")
    _tuple(results, "ablation results", allow_empty=True)
    if not all(isinstance(result, AblationResult) for result in results):
        raise ScientificDesignError("ablation results contains an invalid value")
    ids = tuple(result.ablation_id for result in results)
    if len(set(ids)) != len(ids):
        raise ScientificDesignError("ablation result IDs must be unique")
    contracted = {item.ablation_id: item for item in contract.ablations}
    unknown = set(ids) - set(contracted)
    if unknown:
        raise ScientificPromotionError(
            "fabricated/unregistered ablation result: " + ", ".join(sorted(unknown))
        )
    result_map = {item.ablation_id: item for item in results}
    missing = tuple(
        item.ablation_id
        for item in contract.ablations
        if item.required and (
            item.ablation_id not in result_map or not result_map[item.ablation_id].executed
        )
    )
    if missing:
        raise ScientificPromotionError(
            "required ablations are missing or unexecuted: " + ", ".join(missing)
        )


_SCOPE_RANK = {
    MetricScope.PROXY: 0,
    MetricScope.INTERMEDIATE: 1,
    MetricScope.END_TO_END: 2,
}


def validate_metric_claim_scope(
    contract: EvaluationContract,
    *,
    evidence_metric_id: str,
    claimed_scope: MetricScope,
) -> None:
    """Run a scope diagnostic without minting proxy-promotion authority."""

    if not isinstance(contract, EvaluationContract):
        raise ScientificDesignError("contract must be EvaluationContract")
    if not isinstance(claimed_scope, MetricScope):
        try:
            claimed_scope = MetricScope(claimed_scope)
        except (TypeError, ValueError) as exc:
            raise ScientificDesignError("invalid claimed_scope") from exc
    metric = contract.metric(evidence_metric_id)
    if _SCOPE_RANK[claimed_scope] <= _SCOPE_RANK[metric.scope]:
        return
    if claimed_scope is not MetricScope.END_TO_END:
        raise ScientificPromotionError("metric evidence cannot be promoted beyond its scope")
    raise ScientificPromotionError(
        "proxy metric requires registry-resolved inference verification for an end-to-end claim"
    )


class SuperiorityValidationStatus(StrEnum):
    DIAGNOSTIC_ONLY = "DIAGNOSTIC_ONLY"
    SCIENTIFIC_PROMOTION_AUTHORIZED = "SCIENTIFIC_PROMOTION_AUTHORIZED"


class ScientificResultPromotionStatus(StrEnum):
    """Closed outcome of artifact-only scientific result revalidation."""

    BLOCKED_REQUIRED_SCIENTIFIC_AUTHORITIES_UNAVAILABLE = (
        "BLOCKED_REQUIRED_SCIENTIFIC_AUTHORITIES_UNAVAILABLE"
    )
    BLOCKED_BACKEND_EXECUTION_AUTHORITY_UNAVAILABLE = (
        "BLOCKED_BACKEND_EXECUTION_AUTHORITY_UNAVAILABLE"
    )
    BLOCKED_CONFIRMATION_AUTHORITY_UNAVAILABLE = (
        "BLOCKED_CONFIRMATION_AUTHORITY_UNAVAILABLE"
    )
    SCIENTIFIC_PROMOTION_AUTHORIZED = "SCIENTIFIC_PROMOTION_AUTHORIZED"


class ScientificResultOutcome(StrEnum):
    """Outcome-neutral result semantics, independent of paper worthiness."""

    POSITIVE = "POSITIVE"
    NEGATIVE = "NEGATIVE"
    NULL = "NULL"
    INCONCLUSIVE = "INCONCLUSIVE"
    FALSIFIED = "FALSIFIED"
    TECHNICAL_FAILURE = "TECHNICAL_FAILURE"


class CheckedResultAssessmentStatus(StrEnum):
    AUTHORIZED = "AUTHORIZED"
    BLOCKED_EXTERNAL = "BLOCKED_EXTERNAL"


@dataclass(frozen=True, slots=True)
class ScientificResultAssessmentDecision:
    outcome: ScientificResultOutcome
    hypothesis_status: HypothesisStatus

    def __post_init__(self) -> None:
        _enum(self, "outcome", ScientificResultOutcome)
        _enum(self, "hypothesis_status", HypothesisStatus)
        allowed = {
            ScientificResultOutcome.POSITIVE: frozenset(
                {
                    HypothesisStatus.SUPPORTED,
                    HypothesisStatus.PARTIALLY_SUPPORTED,
                }
            ),
            ScientificResultOutcome.NEGATIVE: frozenset(
                {HypothesisStatus.NOT_SUPPORTED}
            ),
            ScientificResultOutcome.NULL: frozenset(
                {HypothesisStatus.NOT_SUPPORTED}
            ),
            ScientificResultOutcome.INCONCLUSIVE: frozenset(
                {
                    HypothesisStatus.INCONCLUSIVE,
                    HypothesisStatus.NOT_SUPPORTED,
                }
            ),
            ScientificResultOutcome.FALSIFIED: frozenset(
                {HypothesisStatus.FALSIFIED}
            ),
            ScientificResultOutcome.TECHNICAL_FAILURE: frozenset(
                {HypothesisStatus.INCONCLUSIVE}
            ),
        }
        if set(allowed) != set(ScientificResultOutcome) or (
            self.hypothesis_status not in allowed[self.outcome]
        ):
            raise ScientificDesignError(
                "scientific result and hypothesis outcomes are inconsistent"
            )


def derive_scientific_result_assessment(
    policy: HypothesisEvaluationPolicy,
    facts: HypothesisEvaluationFacts,
    *,
    execution_outcome: ScientificExecutionOutcome = (
        ScientificExecutionOutcome.COMPLETED
    ),
) -> ScientificResultAssessmentDecision:
    """Apply the frozen policy without making superiority a prerequisite."""

    if not isinstance(execution_outcome, ScientificExecutionOutcome):
        try:
            execution_outcome = ScientificExecutionOutcome(execution_outcome)
        except (TypeError, ValueError) as exc:
            raise ScientificDesignError(
                "scientific result assessment has an invalid execution outcome"
            ) from exc
    if execution_outcome is not ScientificExecutionOutcome.COMPLETED:
        return ScientificResultAssessmentDecision(
            outcome=ScientificResultOutcome.TECHNICAL_FAILURE,
            hypothesis_status=HypothesisStatus.INCONCLUSIVE,
        )
    hypothesis_status = evaluate_hypothesis_policy(policy, facts)
    if hypothesis_status in {
        HypothesisStatus.SUPPORTED,
        HypothesisStatus.PARTIALLY_SUPPORTED,
    }:
        outcome = ScientificResultOutcome.POSITIVE
    elif hypothesis_status is HypothesisStatus.FALSIFIED:
        outcome = ScientificResultOutcome.FALSIFIED
    elif hypothesis_status is HypothesisStatus.INCONCLUSIVE:
        outcome = ScientificResultOutcome.INCONCLUSIVE
    elif hypothesis_status is HypothesisStatus.NOT_SUPPORTED:
        p_value = facts.adjusted_p_value
        if (
            p_value is not None
            and p_value <= policy.alpha
            and facts.confidence_high < 0.0
        ):
            outcome = ScientificResultOutcome.NEGATIVE
        elif (
            facts.confidence_low >= -policy.falsification_effect
            and facts.confidence_high <= policy.meaningful_effect
        ):
            outcome = ScientificResultOutcome.NULL
        else:
            # Failure to reject or support is not equivalence.  A wide or
            # one-sided interval that still contains a meaningful gain stays
            # inconclusive even though the frozen hypothesis policy records
            # NOT_SUPPORTED for this observation.
            outcome = ScientificResultOutcome.INCONCLUSIVE
    else:  # pragma: no cover - the policy codomain is closed above
        raise ScientificDesignError("hypothesis outcome is not exhaustively mapped")
    return ScientificResultAssessmentDecision(
        outcome=outcome,
        hypothesis_status=hypothesis_status,
    )


def derive_bounded_mean_result_assessment(
    policy: HypothesisEvaluationPolicy,
    result: BoundedMeanInferenceResult,
) -> ScientificResultAssessmentDecision:
    """Retain the interval decision's outcome without a legacy p-gated remap.

    NULL is strictly within the frozen positive margins, not equality to zero.
    This is a pure numerical mapping, not an execution or evidence authority.
    A failed/incomplete execution has no complete numerical result to consume.
    """

    current = _replay_bounded_mean_policy_result(policy, result)
    outcome = {
        BoundedMeanDecision.INCONCLUSIVE: ScientificResultOutcome.INCONCLUSIVE,
        BoundedMeanDecision.FALSIFIED: ScientificResultOutcome.FALSIFIED,
        BoundedMeanDecision.SUPPORTED: ScientificResultOutcome.POSITIVE,
        BoundedMeanDecision.EQUIVALENT_WITHIN_MARGINS: ScientificResultOutcome.NULL,
        BoundedMeanDecision.PARTIALLY_SUPPORTED: ScientificResultOutcome.POSITIVE,
        BoundedMeanDecision.NEGATIVE: ScientificResultOutcome.NEGATIVE,
    }[current.decision]
    return ScientificResultAssessmentDecision(
        outcome=outcome,
        hypothesis_status=_bounded_mean_hypothesis_status(current.decision),
    )


class ScientificAblationAuthorityOutcome(StrEnum):
    """Every valid branch for one exact deterministic ablation review slot."""

    ACCEPTED = "SCIENTIFIC_ABLATION_ACCEPTED"
    REJECTED = "SCIENTIFIC_ABLATION_REJECTED"


@dataclass(frozen=True, slots=True)
class SuperiorityDiagnostic:
    """A value-level consistency result with no scientific authority."""

    contract_sha256: str
    metric_id: str
    claimed_scope: MetricScope
    executed_baseline_ids: tuple[str, ...]
    candidate_value: float
    baseline_value: float
    statistical_artifact_sha256: str
    evaluator_id: str
