@dataclass(frozen=True, slots=True)
class ScientificTimelineReceipt:
    """Ledger-sequence authority for one exact frozen experiment lifecycle."""

    receipt_id: str
    run_id: str
    ledger_path: str
    contract_artifact_sha256: str
    contract_sha256: str
    contract_record_hash: str
    hypothesis_id: str
    experiment_id: str
    stage: ExperimentStage
    experiment_plan_artifact_sha256s: tuple[str, ...]
    experiment_plan_record_hashes: tuple[str, ...]
    frozen_run_spec_artifact_sha256: str
    frozen_run_spec_record_hash: str
    frozen_run_spec_sha256: str
    output_manifest_artifact_sha256: str
    output_manifest_record_hash: str
    design_freeze_event_id: str
    design_freeze_event_hash: str
    design_freeze_event_index: int
    confirmatory_started_event_id: str | None
    confirmatory_started_event_hash: str | None
    confirmatory_started_event_index: int | None
    reveal_event_id: str | None
    reveal_event_hash: str | None
    reveal_event_index: int | None
    result_event_id: str
    result_event_hash: str
    result_event_index: int
    ledger_prefix_head_hash: str
    design_frozen_before_execution: bool
    frozen_before_result_visibility: bool

    def __post_init__(self) -> None:
        for name in ("receipt_id", "run_id", "hypothesis_id", "experiment_id"):
            object.__setattr__(self, name, _identifier(getattr(self, name), name))
        object.__setattr__(self, "ledger_path", _text(self.ledger_path, "ledger_path"))
        _enum(self, "stage", ExperimentStage)
        for name in (
            "contract_artifact_sha256",
            "contract_sha256",
            "contract_record_hash",
            "frozen_run_spec_artifact_sha256",
            "frozen_run_spec_record_hash",
            "frozen_run_spec_sha256",
            "output_manifest_artifact_sha256",
            "output_manifest_record_hash",
            "design_freeze_event_hash",
            "result_event_hash",
            "ledger_prefix_head_hash",
        ):
            object.__setattr__(self, name, _sha256(getattr(self, name), name))
        for name in (
            "experiment_plan_artifact_sha256s",
            "experiment_plan_record_hashes",
        ):
            values = _identifiers(getattr(self, name), name)
            if any(len(value) != 64 for value in values):
                raise ScientificDesignError(f"{name} must contain SHA-256 identities")
            object.__setattr__(self, name, values)
        if len(self.experiment_plan_artifact_sha256s) != len(
            self.experiment_plan_record_hashes
        ):
            raise ScientificDesignError("timeline plan metadata bindings are incomplete")
        for name in ("design_freeze_event_id", "result_event_id"):
            object.__setattr__(self, name, _identifier(getattr(self, name), name))
        for name in ("design_freeze_event_index", "result_event_index"):
            _positive_int(getattr(self, name), name, allow_zero=True)
        if not self.design_freeze_event_index < self.result_event_index:
            raise ScientificPromotionError("design freeze must precede result visibility")
        confirmatory_fields = (
            self.confirmatory_started_event_id,
            self.confirmatory_started_event_hash,
            self.confirmatory_started_event_index,
            self.reveal_event_id,
            self.reveal_event_hash,
            self.reveal_event_index,
        )
        if self.stage is ExperimentStage.CONFIRMATORY:
            if any(value is None for value in confirmatory_fields):
                raise ScientificPromotionError(
                    "confirmatory timeline lacks start or reveal authority"
                )
            assert self.confirmatory_started_event_id is not None
            assert self.confirmatory_started_event_hash is not None
            assert self.confirmatory_started_event_index is not None
            assert self.reveal_event_id is not None
            assert self.reveal_event_hash is not None
            assert self.reveal_event_index is not None
            _identifier(self.confirmatory_started_event_id, "confirmatory_started_event_id")
            _identifier(self.reveal_event_id, "reveal_event_id")
            _sha256(self.confirmatory_started_event_hash, "confirmatory_started_event_hash")
            _sha256(self.reveal_event_hash, "reveal_event_hash")
            _positive_int(
                self.confirmatory_started_event_index,
                "confirmatory_started_event_index",
                allow_zero=True,
            )
            _positive_int(self.reveal_event_index, "reveal_event_index", allow_zero=True)
            if not (
                self.design_freeze_event_index
                < self.confirmatory_started_event_index
                < self.reveal_event_index
                <= self.result_event_index
            ):
                raise ScientificPromotionError(
                    "confirmatory freeze/start/reveal/result order is invalid"
                )
        elif any(value is not None for value in confirmatory_fields):
            raise ScientificPromotionError(
                "exploratory timeline cannot contain confirmatory start/reveal authority"
            )
        if (
            self.design_frozen_before_execution is not True
            or self.frozen_before_result_visibility is not True
            or self.ledger_prefix_head_hash != self.result_event_hash
        ):
            raise ScientificPromotionError("timeline authority is not deterministically valid")

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema_version": SCIENTIFIC_TIMELINE_RECEIPT_SCHEMA,
            "receipt_id": self.receipt_id,
            "run_id": self.run_id,
            "ledger_path": self.ledger_path,
            "contract_artifact_sha256": self.contract_artifact_sha256,
            "contract_sha256": self.contract_sha256,
            "contract_record_hash": self.contract_record_hash,
            "hypothesis_id": self.hypothesis_id,
            "experiment_id": self.experiment_id,
            "stage": self.stage.value,
            "experiment_plan_artifact_sha256s": list(
                self.experiment_plan_artifact_sha256s
            ),
            "experiment_plan_record_hashes": list(self.experiment_plan_record_hashes),
            "frozen_run_spec_artifact_sha256": self.frozen_run_spec_artifact_sha256,
            "frozen_run_spec_record_hash": self.frozen_run_spec_record_hash,
            "frozen_run_spec_sha256": self.frozen_run_spec_sha256,
            "output_manifest_artifact_sha256": self.output_manifest_artifact_sha256,
            "output_manifest_record_hash": self.output_manifest_record_hash,
            "design_freeze_event_id": self.design_freeze_event_id,
            "design_freeze_event_hash": self.design_freeze_event_hash,
            "design_freeze_event_index": self.design_freeze_event_index,
            "confirmatory_started_event_id": self.confirmatory_started_event_id,
            "confirmatory_started_event_hash": self.confirmatory_started_event_hash,
            "confirmatory_started_event_index": self.confirmatory_started_event_index,
            "reveal_event_id": self.reveal_event_id,
            "reveal_event_hash": self.reveal_event_hash,
            "reveal_event_index": self.reveal_event_index,
            "result_event_id": self.result_event_id,
            "result_event_hash": self.result_event_hash,
            "result_event_index": self.result_event_index,
            "ledger_prefix_head_hash": self.ledger_prefix_head_hash,
            "design_frozen_before_execution": self.design_frozen_before_execution,
            "frozen_before_result_visibility": self.frozen_before_result_visibility,
        }

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> ScientificTimelineReceipt:
        expected = set(cls.__dataclass_fields__) | {"schema_version"}
        _require_exact_keys(value, expected, "scientific timeline receipt")
        if value["schema_version"] != SCIENTIFIC_TIMELINE_RECEIPT_SCHEMA:
            raise ScientificPromotionError("unsupported scientific timeline receipt")
        try:
            arguments = {name: value[name] for name in cls.__dataclass_fields__}
            arguments["stage"] = ExperimentStage(arguments["stage"])
            arguments["experiment_plan_artifact_sha256s"] = tuple(
                arguments["experiment_plan_artifact_sha256s"]
            )
            arguments["experiment_plan_record_hashes"] = tuple(
                arguments["experiment_plan_record_hashes"]
            )
            return cls(**arguments)
        except (KeyError, TypeError, ValueError) as exc:
            raise ScientificPromotionError("scientific timeline receipt is malformed") from exc


