def _protocol_json_sequence(value: Any, label: str) -> tuple[Any, ...]:
    if not isinstance(value, list) or len(value) > MAX_ITEMS:
        raise ScientificPromotionError(f"{label} must be a bounded JSON array")
    return tuple(value)


def _parse_scientific_confirmatory_protocol(value: Any) -> ResearchProtocol:
    """Strictly rehydrate the existing frozen ResearchProtocol source owner."""

    _require_exact_keys(
        value,
        {item.name for item in fields(ResearchProtocol)},
        "scientific confirmatory frozen protocol",
    )
    payload = value

    def exact(model: type[Any], raw: Any, label: str) -> Mapping[str, Any]:
        _require_exact_keys(raw, {item.name for item in fields(model)}, label)
        return raw

    try:
        roles_value = exact(
            ProtocolDataRoles,
            payload["data_roles"],
            "scientific confirmatory protocol data roles",
        )
        roles = ProtocolDataRoles(
            **{
                name: _protocol_json_sequence(
                    roles_value[name],
                    f"scientific confirmatory protocol data role {name}",
                )
                for name in ("train", "development", "validation", "holdout")
            }
        )
        candidate_value = exact(
            ProtocolExecutionConditions,
            payload["candidate_conditions"],
            "scientific confirmatory protocol candidate conditions",
        )
        candidate = ProtocolExecutionConditions(**dict(candidate_value))
        baselines = tuple(
            ProtocolBaselineSpec(
                name=exact(
                    ProtocolBaselineSpec,
                    item,
                    "scientific confirmatory protocol baseline",
                )["name"],
                conditions=ProtocolExecutionConditions(
                    **dict(
                        exact(
                            ProtocolExecutionConditions,
                            exact(
                                ProtocolBaselineSpec,
                                item,
                                "scientific confirmatory protocol baseline",
                            )["conditions"],
                            "scientific confirmatory protocol baseline conditions",
                        )
                    )
                ),
            )
            for item in _protocol_json_sequence(
                payload["baseline_set"],
                "scientific confirmatory protocol baselines",
            )
        )
        domain_nulls = tuple(
            ProtocolDomainNullSpec(
                **{
                    **dict(
                        exact(
                            ProtocolDomainNullSpec,
                            item,
                            "scientific confirmatory protocol domain null",
                        )
                    ),
                    "structures_preserved": _protocol_json_sequence(
                        exact(
                            ProtocolDomainNullSpec,
                            item,
                            "scientific confirmatory protocol domain null",
                        )["structures_preserved"],
                        "scientific confirmatory protocol preserved structures",
                    ),
                    "assumptions": _protocol_json_sequence(
                        exact(
                            ProtocolDomainNullSpec,
                            item,
                            "scientific confirmatory protocol domain null",
                        )["assumptions"],
                        "scientific confirmatory protocol domain assumptions",
                    ),
                }
            )
            for item in _protocol_json_sequence(
                payload["domain_nulls"],
                "scientific confirmatory protocol domain nulls",
            )
        )
        tests = tuple(
            ProtocolStatisticalTestSpec(
                **dict(
                    exact(
                        ProtocolStatisticalTestSpec,
                        item,
                        "scientific confirmatory protocol statistical test",
                    )
                )
            )
            for item in _protocol_json_sequence(
                payload["statistical_tests"],
                "scientific confirmatory protocol statistical tests",
            )
        )
        intervals = tuple(
            ProtocolConfidenceIntervalSpec(
                **dict(
                    exact(
                        ProtocolConfidenceIntervalSpec,
                        item,
                        "scientific confirmatory protocol confidence interval",
                    )
                )
            )
            for item in _protocol_json_sequence(
                payload["confidence_intervals"],
                "scientific confirmatory protocol confidence intervals",
            )
        )
        seed_value = exact(
            ProtocolSeedPolicy,
            payload["seed_policy"],
            "scientific confirmatory protocol seed policy",
        )
        protocol = ResearchProtocol(
            study_id=payload["study_id"],
            study_version=payload["study_version"],
            primary_hypothesis=payload["primary_hypothesis"],
            primary_estimand=payload["primary_estimand"],
            primary_metric=payload["primary_metric"],
            secondary_metrics=_protocol_json_sequence(
                payload["secondary_metrics"],
                "scientific confirmatory protocol secondary metrics",
            ),
            unit_of_analysis=payload["unit_of_analysis"],
            resampling_unit=payload["resampling_unit"],
            data_exclusions=_protocol_json_sequence(
                payload["data_exclusions"],
                "scientific confirmatory protocol data exclusions",
            ),
            data_roles=roles,
            candidate_conditions=candidate,
            baseline_set=baselines,
            ablation_set=_protocol_json_sequence(
                payload["ablation_set"],
                "scientific confirmatory protocol ablations",
            ),
            negative_controls=_protocol_json_sequence(
                payload["negative_controls"],
                "scientific confirmatory protocol negative controls",
            ),
            domain_nulls=domain_nulls,
            statistical_tests=tests,
            confidence_intervals=intervals,
            multiple_comparison_correction=payload[
                "multiple_comparison_correction"
            ],
            seed_policy=ProtocolSeedPolicy(
                **{
                    **dict(seed_value),
                    "seeds": _protocol_json_sequence(
                        seed_value["seeds"],
                        "scientific confirmatory protocol seeds",
                    ),
                }
            ),
            compute_budget=ProtocolComputeBudget(
                **dict(
                    exact(
                        ProtocolComputeBudget,
                        payload["compute_budget"],
                        "scientific confirmatory protocol compute budget",
                    )
                )
            ),
            stopping_rules=_protocol_json_sequence(
                payload["stopping_rules"],
                "scientific confirmatory protocol stopping rules",
            ),
            decision_ladder=_protocol_json_sequence(
                payload["decision_ladder"],
                "scientific confirmatory protocol decision ladder",
            ),
            claim_scope_contract=payload["claim_scope_contract"],
            interpretation_rules=ProtocolInterpretationRules(
                **dict(
                    exact(
                        ProtocolInterpretationRules,
                        payload["interpretation_rules"],
                        "scientific confirmatory protocol interpretation rules",
                    )
                )
            ),
            validity_reserve_fraction=payload["validity_reserve_fraction"],
            reserve_basis=payload["reserve_basis"],
            parent_protocol_hash=payload["parent_protocol_hash"],
            revision_reason=payload["revision_reason"],
        )
        validate_protocol(protocol)
    except (KeyError, TypeError, ValueError, ProtocolValidationError) as exc:
        raise ScientificPromotionError(
            "scientific confirmatory frozen protocol is malformed"
        ) from exc
    try:
        if safe_json_loads(canonical_json_bytes(protocol.canonical_dict)) != value:
            raise ScientificPromotionError(
                "scientific confirmatory frozen protocol does not round-trip"
            )
    except (UnsafeSerializationError, TypeError, ValueError) as exc:
        raise ScientificPromotionError(
            "scientific confirmatory frozen protocol is not canonical"
        ) from exc
    return protocol


def _require_scientific_protocol_contract_crosswalk(
    protocol: ResearchProtocol,
    contract: EvaluationContract,
) -> None:
    """Replay the existing pure crosswalk, without downstream source authority.

    Matching these fields is not a freeze, reserve, custody or confirmation
    authorization. Source owners must independently establish those guarantees.
    """

    primary = contract.hypothesis_register.primary
    required_ablations = tuple(
        item.ablation_id for item in contract.ablations if item.required
    )
    baseline_names = tuple(item.name for item in contract.baseline_registry.entries)
    if (
        protocol.primary_hypothesis != primary.statement
        or protocol.primary_metric != contract.primary_metric.metric_id
        or protocol.resampling_unit.casefold()
        != contract.statistical_plan.resampling_unit.casefold()
        or protocol.data_exclusions != contract.dataset.exclusions
        or protocol.data_roles.train != (contract.dataset.train_split_id,)
        or protocol.data_roles.development
        != (contract.dataset.development_split_id,)
        or protocol.data_roles.validation
        != (contract.dataset.validation_split_id,)
        or protocol.data_roles.holdout
        != (contract.dataset.confirmatory_split_id,)
        or protocol.seed_policy.seeds != contract.seed_reporting.seeds
        or protocol.compute_budget.max_runs != contract.compute_budget.max_runs
        or not _same_number(
            protocol.compute_budget.max_wall_seconds,
            contract.compute_budget.max_wall_seconds,
        )
        or protocol.compute_budget.max_cpu_workers
        != contract.compute_budget.max_cpu_workers
        or protocol.compute_budget.max_gpu_jobs
        != contract.compute_budget.max_gpu_jobs
        or protocol.stopping_rules != contract.stopping_criteria
        or protocol.ablation_set != required_ablations
        or protocol.multiple_comparison_correction.casefold()
        != contract.statistical_plan.multiplicity_correction.casefold()
        or not protocol.statistical_tests
        or protocol.statistical_tests[0].name
        != contract.statistical_plan.primary_test
        or not _same_number(
            protocol.statistical_tests[0].alpha,
            contract.statistical_plan.alpha,
        )
        or protocol.candidate_conditions.preprocessing
        != contract.candidate_conditions.preprocessing
        or protocol.candidate_conditions.tuning_budget
        != contract.candidate_conditions.tuning_trials
        or not _same_number(
            protocol.candidate_conditions.compute_budget,
            contract.candidate_conditions.compute_budget,
        )
        or tuple(item.name for item in protocol.baseline_set) != baseline_names
    ):
        raise ScientificPromotionError(
            "frozen custody protocol is not the exact vNext confirmatory design"
        )
    for protocol_baseline, contract_baseline in zip(
        protocol.baseline_set,
        contract.baseline_registry.entries,
        strict=True,
    ):
        if (
            protocol_baseline.conditions.preprocessing
            != contract_baseline.conditions.preprocessing
            or protocol_baseline.conditions.tuning_budget
            != contract_baseline.conditions.tuning_trials
            or not _same_number(
                protocol_baseline.conditions.compute_budget,
                contract_baseline.conditions.compute_budget,
            )
        ):
            raise ScientificPromotionError(
                "frozen custody protocol baseline semantics are substituted"
            )


def _scientific_confirmatory_protocol_sources(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    expected_ledger_run_id: str,
    expected_execution_run_id: str,
    evaluation_contract_freeze_receipt_artifact_sha256: str,
    scientific_execution_preparation_artifact_sha256: str,
    protocol_artifact_sha256: str,
    fresh_custody_receipt_artifact_sha256: str,
    dataset_authority_artifact_sha256: str,
    split_authority_artifact_sha256s: tuple[str, ...],
) -> _ScientificConfirmatoryProtocolSources:
    """Freshly replay every prospective input and its semantic crosswalk."""

    expected_ledger_run_id = _identifier(
        expected_ledger_run_id,
        "scientific confirmatory ledger run ID",
    )
    expected_execution_run_id = _identifier(
        expected_execution_run_id,
        "scientific confirmatory execution run ID",
    )
    if len(split_authority_artifact_sha256s) != 4:
        raise ScientificPromotionError(
            "scientific confirmatory protocol requires four split authorities"
        )
    for digest in (
        evaluation_contract_freeze_receipt_artifact_sha256,
        scientific_execution_preparation_artifact_sha256,
        protocol_artifact_sha256,
        fresh_custody_receipt_artifact_sha256,
        dataset_authority_artifact_sha256,
        *split_authority_artifact_sha256s,
    ):
        _sha256(digest, "scientific confirmatory protocol source")

    freeze_record, freeze_value = _load_checked_superiority_artifact(
        registry,
        evaluation_contract_freeze_receipt_artifact_sha256,
        logical_type=EVALUATION_CONTRACT_FREEZE_GATE_RECEIPT_LOGICAL_TYPE,
        creator_role=Role.CLAIM_VERIFIER,
    )
    freeze_unchecked = EvaluationContractFreezeGateReceipt.from_dict(freeze_value)
    contract = require_frozen_evaluation_contract(
        registry,
        contract_artifact_sha256=freeze_unchecked.contract_artifact_sha256,
    )
    if contract.scientific_execution_admissibility_policy is None:
        raise ScientificPromotionError(
            "scientific confirmation requires a typed v3 admissibility policy"
        )
    freeze = require_evaluation_contract_freeze_gate_receipt(
        registry,
        ledger,
        receipt_artifact_sha256=freeze_record.sha256,
        expected_run_id=expected_ledger_run_id,
        expected_contract_id=contract.contract_id,
        contract=contract,
    )
    contract_record = registry.get_metadata(freeze.contract_artifact_sha256)
    preparation = require_scientific_execution_preparation(
        registry,
        ledger,
        preparation_artifact_sha256=(
            scientific_execution_preparation_artifact_sha256
        ),
        expected_ledger_run_id=expected_ledger_run_id,
        expected_execution_run_id=expected_execution_run_id,
    )
    preparation_record = registry.get_metadata(
        scientific_execution_preparation_artifact_sha256
    )
    spec = require_scientific_execution_run_spec(
        registry,
        frozen_run_spec_artifact_sha256=(
            preparation.frozen_run_spec_artifact_sha256
        ),
    )
    spec_record = registry.get_metadata(
        preparation.frozen_run_spec_artifact_sha256
    )

    protocol_record, protocol_wrapper = _load_checked_superiority_artifact(
        registry,
        protocol_artifact_sha256,
        logical_type="frozen_protocol",
        creator_role=Role.PROTOCOL_DESIGNER,
    )
    if (
        protocol_record.parent_artifacts
        or "protocol" not in protocol_wrapper
        or "protocol_sha256" not in protocol_wrapper
        or not isinstance(protocol_wrapper["protocol"], Mapping)
    ):
        raise ScientificPromotionError(
            "scientific confirmatory protocol wrapper is not frozen root authority"
        )
    protocol = _parse_scientific_confirmatory_protocol(
        protocol_wrapper["protocol"]
    )
    if protocol_wrapper["protocol_sha256"] != protocol.sha256:
        raise ScientificPromotionError(
            "scientific confirmatory protocol wrapper hash is substituted"
        )
    fresh_record, fresh_value = _load_checked_superiority_artifact(
        registry,
        fresh_custody_receipt_artifact_sha256,
        logical_type="fresh_custody_receipt",
        creator_role=Role.HOLDOUT_CUSTODIAN,
    )
    if (
        fresh_value.get("study_id") != protocol.study_id
        or fresh_value.get("study_version") != protocol.study_version
    ):
        raise ScientificPromotionError(
            "fresh custody receipt names another frozen protocol"
        )

    from .research_state import (
        SplitRole,
        require_scientific_dataset_authority,
        require_scientific_dataset_split_authority,
    )

    dataset = require_scientific_dataset_authority(
        registry,
        ledger,
        run_id=expected_ledger_run_id,
        authority_artifact_hash=dataset_authority_artifact_sha256,
        expected_dataset_id=contract.dataset.dataset_id,
    )
    dataset_record = registry.get_metadata(dataset_authority_artifact_sha256)
    expected_splits = (
        (SplitRole.TRAIN, contract.dataset.train_split_id),
        (SplitRole.DEVELOPMENT, contract.dataset.development_split_id),
        (SplitRole.VALIDATION, contract.dataset.validation_split_id),
        (SplitRole.CONFIRMATORY, contract.dataset.confirmatory_split_id),
    )
    splits = tuple(
        require_scientific_dataset_split_authority(
            registry,
            ledger,
            run_id=expected_ledger_run_id,
            split_authority_artifact_hash=digest,
            expected_split_id=split_id,
            expected_split_role=role,
        )
        for digest, (role, split_id) in zip(
            split_authority_artifact_sha256s,
            expected_splits,
            strict=True,
        )
    )
    split_records = tuple(
        registry.get_metadata(digest)
        for digest in split_authority_artifact_sha256s
    )

    primary = contract.hypothesis_register.primary
    required_ablations = tuple(
        item.ablation_id for item in contract.ablations if item.required
    )
    if (
        freeze.stage is not ExperimentStage.CONFIRMATORY
        or freeze.frozen_run_spec_artifact_sha256 != spec_record.sha256
        or preparation.frozen_run_spec_artifact_sha256 != spec_record.sha256
        or spec.phase is not ExperimentPhase.CONFIRMATORY
        or spec.hypothesis_id != primary.hypothesis_id
        or spec.experiment_id != primary.planned_experiment
        or spec.seeds != contract.seed_reporting.seeds
        or spec.required_ablations != required_ablations
        or spec.evaluator_sha256 != preparation.input_artifact_sha256s[-1]
        or dataset.evaluation_contract_artifact_hash != contract_record.sha256
        or any(
            item.evaluation_contract_artifact_hash != contract_record.sha256
            or item.dataset_authority_artifact_hash != dataset_record.sha256
            for item in splits
        )
    ):
        raise ScientificPromotionError(
            "frozen custody protocol is not the exact vNext confirmatory design"
        )
    _require_scientific_protocol_contract_crosswalk(protocol, contract)
    return _ScientificConfirmatoryProtocolSources(
        freeze_record=freeze_record,
        freeze=freeze,
        contract_record=contract_record,
        contract=contract,
        preparation_record=preparation_record,
        preparation=preparation,
        spec_record=spec_record,
        spec=spec,
        protocol_record=protocol_record,
        protocol=protocol,
        fresh_custody_record=fresh_record,
        dataset_record=dataset_record,
        dataset=dataset,
        split_records=split_records,
        splits=splits,
    )


def _scientific_confirmatory_protocol_binding_value(
    *,
    binding_id: str,
    sources: _ScientificConfirmatoryProtocolSources,
) -> ScientificConfirmatoryProtocolBinding:
    records = sources.records
    contract = sources.contract
    return ScientificConfirmatoryProtocolBinding(
        binding_id=binding_id,
        ledger_run_id=sources.freeze.run_id,
        execution_run_id=sources.spec.run_id,
        evaluation_contract_freeze_receipt_artifact_sha256=(
            sources.freeze_record.sha256
        ),
        evaluation_contract_freeze_receipt_record_hash=str(
            sources.freeze_record.record_hash
        ),
        contract_artifact_sha256=sources.contract_record.sha256,
        contract_record_hash=str(sources.contract_record.record_hash),
        contract_sha256=contract.sha256,
        scientific_execution_preparation_artifact_sha256=(
            sources.preparation_record.sha256
        ),
        scientific_execution_preparation_record_hash=str(
            sources.preparation_record.record_hash
        ),
        frozen_run_spec_artifact_sha256=sources.spec_record.sha256,
        frozen_run_spec_record_hash=str(sources.spec_record.record_hash),
        frozen_run_spec_sha256=sources.spec.sha256,
        protocol_artifact_sha256=sources.protocol_record.sha256,
        protocol_record_hash=str(sources.protocol_record.record_hash),
        protocol_sha256=sources.protocol.sha256,
        fresh_custody_receipt_artifact_sha256=(
            sources.fresh_custody_record.sha256
        ),
        fresh_custody_receipt_record_hash=str(
            sources.fresh_custody_record.record_hash
        ),
        dataset_authority_artifact_sha256=sources.dataset_record.sha256,
        dataset_authority_record_hash=str(sources.dataset_record.record_hash),
        split_authority_artifact_sha256s=tuple(
            item.sha256 for item in sources.split_records
        ),
        split_authority_record_hashes=tuple(
            str(item.record_hash) for item in sources.split_records
        ),
        study_id=sources.protocol.study_id,
        study_version=sources.protocol.study_version,
        hypothesis_id=contract.hypothesis_register.primary.hypothesis_id,
        experiment_id=sources.spec.experiment_id,
        metric_id=contract.primary_metric.metric_id,
        metric_unit=contract.primary_metric.unit,
        metric_direction=contract.primary_metric.direction,
        metric_scope=contract.primary_metric.scope,
        evaluator_id=contract.candidate_conditions.evaluator,
        dataset_id=contract.dataset.dataset_id,
        split_ids=tuple(item.split_id for item in sources.splits),
        seed_order=sources.spec.seeds,
        source_artifact_sha256s=tuple(item.sha256 for item in records),
        source_artifact_record_hashes=tuple(
            str(item.record_hash) for item in records
        ),
    )


def _scientific_confirmatory_live_event(
    events: tuple[LedgerEvent, ...],
    *,
    event_id: str,
    event_hash: str,
) -> tuple[int, LedgerEvent]:
    matches = tuple(
        (index, event)
        for index, event in enumerate(events)
        if event.event_id == event_id and event.event_hash == event_hash
    )
    if len(matches) != 1:
        raise ScientificPromotionError(
            "scientific confirmatory source event is absent or ambiguous"
        )
    index, event = matches[0]
    if any(
        later.event_type == "CORRECTION"
        and later.supersedes_event_id == event.event_id
        for later in events[index + 1 :]
    ):
        raise ScientificPromotionError(
            "scientific confirmatory source event was superseded"
        )
    return index, event


def _scientific_confirmatory_custody_freeze_event(
    events: tuple[LedgerEvent, ...],
    *,
    run_id: str,
    record: ArtifactRecord,
) -> tuple[int, LedgerEvent]:
    matches: list[tuple[int, LedgerEvent]] = []
    for index, event in enumerate(events):
        metadata = _event_metadata_value(event)
        binding = metadata.get("fresh_custody")
        if (
            event.run_id == run_id
            and event.event_type == "CHECKPOINT"
            and event.actor_role is Role.HOLDOUT_CUSTODIAN
            and isinstance(binding, Mapping)
            and binding.get("artifact_sha256") == record.sha256
        ):
            hashes = metadata.get("artifact_record_hashes")
            types = metadata.get("artifact_types")
            if (
                event.artifact_hashes != (record.sha256,)
                or hashes != [str(record.record_hash)]
                or types != [record.logical_type]
            ):
                raise ScientificPromotionError(
                    "fresh custody event metadata is substituted"
                )
            matches.append((index, event))
    if len(matches) != 1:
        raise ScientificPromotionError(
            "scientific confirmation requires one exact fresh-custody checkpoint"
        )
    index, event = matches[0]
    if event.event_hash is None or any(
        later.event_type == "CORRECTION"
        and later.supersedes_event_id == event.event_id
        for later in events[index + 1 :]
    ):
        raise ScientificPromotionError("fresh custody checkpoint is stale")
    return index, event


def _matching_scientific_confirmatory_protocol_records(
    registry: ArtifactRegistry,
    records: tuple[ArtifactRecord, ...],
    *,
    binding: ScientificConfirmatoryProtocolBinding,
) -> tuple[tuple[ArtifactRecord, ScientificConfirmatoryProtocolBinding], ...]:
    matches: list[tuple[ArtifactRecord, ScientificConfirmatoryProtocolBinding]] = []
    for record in records:
        if record.logical_type != SCIENTIFIC_CONFIRMATORY_PROTOCOL_BINDING_LOGICAL_TYPE:
            continue
        try:
            value = safe_json_loads(registry.get_bytes(record.sha256))
            candidate = ScientificConfirmatoryProtocolBinding.from_dict(value)
        except (ArtifactError, UnsafeSerializationError, ValidationError) as exc:
            raise ScientificPromotionError(
                "scientific confirmatory protocol-binding slot is malformed"
            ) from exc
        if (
            record.record_hash is None
            or record.origin != _SCIENTIFIC_CONFIRMATORY_PROTOCOL_BINDING_ORIGIN
            or record.creator_role is not Role.PROTOCOL_DESIGNER
            or record.creation_command
            != _SCIENTIFIC_CONFIRMATORY_PROTOCOL_BINDING_COMMAND
            or record.schema_version != "1.0"
            or record.mime_type != "application/json"
            or record.validation_result != "PASS"
            or record.frozen is not True
            or record.parent_artifacts != candidate.direct_source_artifact_sha256s
            or registry.get_bytes(record.sha256)
            != canonical_json_bytes(candidate.to_dict()) + b"\n"
        ):
            raise ScientificPromotionError(
                "scientific confirmatory protocol binding is not source-owned"
            )
        if (
            candidate.binding_id == binding.binding_id
            or candidate.execution_run_id == binding.execution_run_id
            or candidate.scientific_execution_preparation_artifact_sha256
            == binding.scientific_execution_preparation_artifact_sha256
        ):
            matches.append((record, candidate))
    if len(matches) > 1:
        raise ScientificPromotionError(
            "scientific confirmatory protocol-binding slot is ambiguous"
        )
    return tuple(matches)


def _scientific_confirmatory_protocol_event_binding(
    record: ArtifactRecord,
    binding: ScientificConfirmatoryProtocolBinding,
    sources: _ScientificConfirmatoryProtocolSources,
) -> dict[str, Any]:
    return {
        "schema_version": SCIENTIFIC_CONFIRMATORY_PROTOCOL_BINDING_EVENT_SCHEMA,
        "kind": "SCIENTIFIC_CONFIRMATORY_PROTOCOL_BOUND",
        "binding_id": binding.binding_id,
        "ledger_run_id": binding.ledger_run_id,
        "execution_run_id": binding.execution_run_id,
        "binding_artifact_sha256": record.sha256,
        "binding_record_hash": str(record.record_hash),
        "source_artifact_sha256s": [item.sha256 for item in sources.records],
        "source_artifact_record_hashes": [
            str(item.record_hash) for item in sources.records
        ],
        "authority_scope": binding.authority_scope,
        "scientific_evidence": False,
    }


def _matching_scientific_confirmatory_protocol_events(
    events: tuple[LedgerEvent, ...],
    *,
    binding: ScientificConfirmatoryProtocolBinding,
) -> tuple[tuple[int, LedgerEvent, Mapping[str, Any]], ...]:
    matches: list[tuple[int, LedgerEvent, Mapping[str, Any]]] = []
    for index, event in enumerate(events):
        candidate = _event_metadata_value(event).get(
            "scientific_confirmatory_protocol_binding"
        )
        if not isinstance(candidate, Mapping):
            continue
        if (
            candidate.get("binding_id") == binding.binding_id
            or candidate.get("execution_run_id") == binding.execution_run_id
        ):
            matches.append((index, event, candidate))
    if len(matches) > 1:
        raise ScientificPromotionError(
            "scientific confirmatory protocol-binding event is ambiguous"
        )
    return tuple(matches)


def _validate_scientific_confirmatory_protocol_event(
    event: LedgerEvent,
    event_index: int,
    events: tuple[LedgerEvent, ...],
    *,
    record: ArtifactRecord,
    binding: ScientificConfirmatoryProtocolBinding,
    sources: _ScientificConfirmatoryProtocolSources,
) -> None:
    event_binding = _scientific_confirmatory_protocol_event_binding(
        record,
        binding,
        sources,
    )
    all_records = (record, *sources.records)
    metadata = _event_metadata_value(event)
    if (
        event.event_hash is None
        or event.run_id != binding.ledger_run_id
        or event.actor_role is not Role.PROTOCOL_DESIGNER
        or event.event_type != "CHECKPOINT"
        or event.state_before != event.state_after
        or event.artifact_hashes
        != tuple(item.sha256 for item in all_records)
        or event.code_version
        != SCIENTIFIC_CONFIRMATORY_PROTOCOL_BINDING_EVENT_SCHEMA
        or event.configuration_hash != _canonical_hash(event_binding)
        or event.dataset_identifiers
        != (binding.dataset_id, *binding.split_ids)
        or event.random_seeds != binding.seed_order
        or event.evaluator_outputs
        or event.reason
        != "froze exact vNext and custody protocol crosswalk before confirmation"
        or set(metadata)
        != {
            "artifact_types",
            "artifact_record_hashes",
            "scientific_confirmatory_protocol_binding",
        }
        or metadata["artifact_types"]
        != [item.logical_type for item in all_records]
        or metadata["artifact_record_hashes"]
        != [str(item.record_hash) for item in all_records]
        or metadata["scientific_confirmatory_protocol_binding"]
        != event_binding
        or any(
            later.event_type == "CORRECTION"
            and later.supersedes_event_id == event.event_id
            for later in events[event_index + 1 :]
        )
    ):
        raise ScientificPromotionError(
            "scientific confirmatory protocol-binding event is substituted or stale"
        )
    if not (
        sources.freeze.design_freeze_event_index
        < sources.preparation.ledger_event_index
        < event_index
    ):
        raise ScientificPromotionError(
            "scientific confirmatory protocol binding is not prospective"
        )


def register_scientific_confirmatory_protocol_binding(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    binding_id: str,
    expected_ledger_run_id: str,
    expected_execution_run_id: str,
    evaluation_contract_freeze_receipt_artifact_sha256: str,
    scientific_execution_preparation_artifact_sha256: str,
    protocol_artifact_sha256: str,
    fresh_custody_receipt_artifact_sha256: str,
    dataset_authority_artifact_sha256: str,
    split_authority_artifact_sha256s: tuple[str, ...],
) -> ArtifactRecord:
    """Publish a non-evidentiary crosswalk before confirmation starts."""

    binding_id = _identifier(binding_id, "scientific confirmatory binding ID")
    before = _locked_checked_result_authority_snapshot(
        registry,
        ledger,
        ensure_storage=True,
    )
    if any(event.run_id != expected_ledger_run_id for event in before[1].events):
        raise ScientificPromotionError(
            "scientific confirmatory ledger has another run identity"
        )
    sources = _scientific_confirmatory_protocol_sources(
        registry,
        ledger,
        expected_ledger_run_id=expected_ledger_run_id,
        expected_execution_run_id=expected_execution_run_id,
        evaluation_contract_freeze_receipt_artifact_sha256=(
            evaluation_contract_freeze_receipt_artifact_sha256
        ),
        scientific_execution_preparation_artifact_sha256=(
            scientific_execution_preparation_artifact_sha256
        ),
        protocol_artifact_sha256=protocol_artifact_sha256,
        fresh_custody_receipt_artifact_sha256=(
            fresh_custody_receipt_artifact_sha256
        ),
        dataset_authority_artifact_sha256=dataset_authority_artifact_sha256,
        split_authority_artifact_sha256s=split_authority_artifact_sha256s,
    )
    binding = _scientific_confirmatory_protocol_binding_value(
        binding_id=binding_id,
        sources=sources,
    )
    _, custody_event = _scientific_confirmatory_custody_freeze_event(
        before[1].events,
        run_id=expected_ledger_run_id,
        record=sources.fresh_custody_record,
    )
    if (
        custody_event.event_hash is None
        or any(
            event.event_type in {"CONFIRMATORY_STARTED", "CONFIRMATORY_COMPLETED"}
            for event in before[1].events
        )
        or any(
            record.logical_type == "experiment_output_manifest"
            and sources.spec_record.sha256 in record.parent_artifacts
            for record in before[0].records
        )
    ):
        raise ScientificPromotionError(
            "scientific confirmatory protocol binding is too late"
        )
    data = canonical_json_bytes(binding.to_dict()) + b"\n"
    digest = hashlib.sha256(data).hexdigest()
    matches = _matching_scientific_confirmatory_protocol_records(
        registry,
        before[0].records,
        binding=binding,
    )
    existing: ArtifactRecord | None = None
    if matches:
        existing, prior = matches[0]
        if existing.sha256 != digest or prior != binding:
            raise ScientificPromotionError(
                "scientific confirmatory protocol slot has a competing binding"
            )
    prior_events = _matching_scientific_confirmatory_protocol_events(
        before[1].events,
        binding=binding,
    )
    missing_record = int(existing is None)
    missing_event = int(not prior_events)
    if before[0].count + missing_record > MAX_REGISTRY_RECORDS:
        raise ScientificPromotionError(
            "scientific confirmatory protocol binding exceeds registry capacity"
        )
    if before[1].event_count + missing_event > MAX_LEDGER_EVENTS:
        raise ScientificPromotionError(
            "scientific confirmatory protocol binding exceeds ledger capacity"
        )
    if (
        missing_event
        and before[1].valid_prefix_bytes
        + _MAX_SCIENTIFIC_CONFIRMATORY_EVENT_BYTES
        > MAX_LEDGER_BYTES
    ):
        raise ScientificPromotionError(
            "scientific confirmatory protocol binding exceeds ledger byte capacity"
        )
    registry_guard = registry._open_mutation_lock()
    try:
        ledger_guard = ledger._open_lock()
        try:
            locked_registry = registry._verify_all_locked(
                registry_guard,
                raise_on_error=True,
            )
            locked_ledger = ledger._validate_bytes(
                ledger._read_raw_locked(ledger_guard)
            )
            if (
                not locked_ledger.valid
                or locked_registry != before[0]
                or locked_ledger != before[1]
            ):
                raise ScientificPromotionError(
                    "scientific confirmatory protocol sources changed before commit"
                )
            record = existing
            if record is None:
                record = registry._put_bytes_locked(
                    registry_guard,
                    data,
                    logical_type=(
                        SCIENTIFIC_CONFIRMATORY_PROTOCOL_BINDING_LOGICAL_TYPE
                    ),
                    origin=_SCIENTIFIC_CONFIRMATORY_PROTOCOL_BINDING_ORIGIN,
                    creator_role=Role.PROTOCOL_DESIGNER,
                    creation_command=(
                        _SCIENTIFIC_CONFIRMATORY_PROTOCOL_BINDING_COMMAND
                    ),
                    parent_artifacts=binding.direct_source_artifact_sha256s,
                    schema_version="1.0",
                    mime_type="application/json",
                    validation_result="PASS",
                    frozen=True,
                    created_at=None,
                )
            event_binding = _scientific_confirmatory_protocol_event_binding(
                record,
                binding,
                sources,
            )
            resolved = _matching_scientific_confirmatory_protocol_events(
                locked_ledger.events,
                binding=binding,
            )
            if resolved:
                event_index, event, candidate = resolved[0]
                if dict(candidate) != event_binding:
                    raise ScientificPromotionError(
                        "scientific confirmatory protocol event is competing"
                    )
            else:
                state = _timeline_state(locked_ledger.events)
                event = LedgerEvent.create(
                    run_id=expected_ledger_run_id,
                    actor_role=Role.PROTOCOL_DESIGNER,
                    state_before=state,
                    requested_state_after=state,
                    artifact_hashes=(
                        record.sha256,
                        *(item.sha256 for item in sources.records),
                    ),
                    code_version=(
                        SCIENTIFIC_CONFIRMATORY_PROTOCOL_BINDING_EVENT_SCHEMA
                    ),
                    configuration_hash=_canonical_hash(event_binding),
                    dataset_identifiers=(binding.dataset_id, *binding.split_ids),
                    random_seeds=binding.seed_order,
                    evaluator_outputs=(),
                    reason=(
                        "froze exact vNext and custody protocol crosswalk before confirmation"
                    ),
                    prior_event_hash=locked_ledger.head_hash,
                    event_type="CHECKPOINT",
                    metadata={
                        "artifact_types": [
                            record.logical_type,
                            *(item.logical_type for item in sources.records),
                        ],
                        "artifact_record_hashes": [
                            str(record.record_hash),
                            *(str(item.record_hash) for item in sources.records),
                        ],
                        "scientific_confirmatory_protocol_binding": event_binding,
                    },
                )
                if (
                    len(canonical_json_bytes(event.to_dict()) + b"\n")
                    > _MAX_SCIENTIFIC_CONFIRMATORY_EVENT_BYTES
                ):
                    raise ScientificPromotionError(
                        "scientific confirmatory protocol event exceeds its bound"
                    )

                def build(current: LedgerValidationResult) -> LedgerEvent:
                    if current != locked_ledger:
                        raise ScientificPromotionError(
                            "scientific confirmatory protocol ledger changed during commit"
                        )
                    return event

                event = ledger._append_locked(ledger_guard, build)
                event_index = len(locked_ledger.events)
            committed_registry = registry._verify_all_locked(
                registry_guard,
                raise_on_error=True,
            )
            committed_ledger = ledger._validate_bytes(
                ledger._read_raw_locked(ledger_guard)
            )
            if (
                committed_registry.count != before[0].count + missing_record
                or committed_ledger.event_count
                != before[1].event_count + missing_event
            ):
                raise ScientificPromotionError(
                    "scientific confirmatory protocol commit is incomplete"
                )
            _validate_scientific_confirmatory_protocol_event(
                event,
                event_index,
                committed_ledger.events,
                record=record,
                binding=binding,
                sources=sources,
            )
            registry._verify_mutation_namespace(registry_guard)
        finally:
            ledger._unlock(ledger_guard)
    finally:
        registry._unlock_mutation(registry_guard)
    return_record = registry.get_metadata(digest)
    require_scientific_confirmatory_protocol_binding(
        registry,
        ledger,
        binding_artifact_sha256=return_record.sha256,
        expected_ledger_run_id=expected_ledger_run_id,
        expected_execution_run_id=expected_execution_run_id,
    )
    return return_record


def require_scientific_confirmatory_protocol_binding(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    binding_artifact_sha256: str,
    expected_ledger_run_id: str,
    expected_execution_run_id: str,
) -> ScientificConfirmatoryProtocolBinding:
    """Freshly replay the exact prospective crosswalk and publication."""

    before = _locked_checked_result_authority_snapshot(registry, ledger)
    record, value = _load_checked_superiority_artifact(
        registry,
        binding_artifact_sha256,
        logical_type=SCIENTIFIC_CONFIRMATORY_PROTOCOL_BINDING_LOGICAL_TYPE,
        creator_role=Role.PROTOCOL_DESIGNER,
    )
    binding = ScientificConfirmatoryProtocolBinding.from_dict(value)
    if (
        binding.ledger_run_id != expected_ledger_run_id
        or binding.execution_run_id != expected_execution_run_id
        or record.parent_artifacts != binding.direct_source_artifact_sha256s
    ):
        raise ScientificPromotionError(
            "scientific confirmatory protocol binding names another closure"
        )
    sources = _scientific_confirmatory_protocol_sources(
        registry,
        ledger,
        expected_ledger_run_id=expected_ledger_run_id,
        expected_execution_run_id=expected_execution_run_id,
        evaluation_contract_freeze_receipt_artifact_sha256=(
            binding.evaluation_contract_freeze_receipt_artifact_sha256
        ),
        scientific_execution_preparation_artifact_sha256=(
            binding.scientific_execution_preparation_artifact_sha256
        ),
        protocol_artifact_sha256=binding.protocol_artifact_sha256,
        fresh_custody_receipt_artifact_sha256=(
            binding.fresh_custody_receipt_artifact_sha256
        ),
        dataset_authority_artifact_sha256=(
            binding.dataset_authority_artifact_sha256
        ),
        split_authority_artifact_sha256s=(
            binding.split_authority_artifact_sha256s
        ),
    )
    expected = _scientific_confirmatory_protocol_binding_value(
        binding_id=binding.binding_id,
        sources=sources,
    )
    if binding != expected:
        raise ScientificPromotionError(
            "scientific confirmatory protocol binding differs from source replay"
        )
    if _matching_scientific_confirmatory_protocol_records(
        registry,
        before[0].records,
        binding=binding,
    ) != ((record, binding),):
        raise ScientificPromotionError(
            "scientific confirmatory protocol-binding slot is ambiguous"
        )
    events = _matching_scientific_confirmatory_protocol_events(
        before[1].events,
        binding=binding,
    )
    if len(events) != 1:
        raise ScientificPromotionError(
            "scientific confirmatory protocol binding lacks its publication"
        )
    event_index, event, candidate = events[0]
    if dict(candidate) != _scientific_confirmatory_protocol_event_binding(
        record,
        binding,
        sources,
    ):
        raise ScientificPromotionError(
            "scientific confirmatory protocol-binding publication is competing"
        )
    _validate_scientific_confirmatory_protocol_event(
        event,
        event_index,
        before[1].events,
        record=record,
        binding=binding,
        sources=sources,
    )
    after = _locked_checked_result_authority_snapshot(registry, ledger)
    if after != before:
        raise ScientificPromotionError(
            "scientific confirmatory protocol sources changed during replay"
        )
    return binding


@dataclass(frozen=True, slots=True)
class _ScientificConfirmatoryTimelineSources:
    binding_record: ArtifactRecord
    binding: ScientificConfirmatoryProtocolBinding
    freeze: EvaluationContractFreezeGateReceipt
    contract_record: ArtifactRecord
    preparation_record: ArtifactRecord
    preparation: Any
    execution_record: ArtifactRecord
    execution: Any
    manifest_record: ArtifactRecord
    projection_record: ArtifactRecord
    projection: Any
    legacy_timeline_record: ArtifactRecord
    legacy_timeline: ConfirmatoryTimelineReceipt
    confirmation_record: ArtifactRecord
    confirmation: Any
    protocol_binding_event_index: int
    protocol_binding_event: LedgerEvent
    custody_freeze_event_index: int
    custody_freeze_event: LedgerEvent

    @property
    def direct_records(self) -> tuple[ArtifactRecord, ...]:
        return (
            self.binding_record,
            self.execution_record,
            self.projection_record,
            self.legacy_timeline_record,
            self.confirmation_record,
        )


def _scientific_confirmatory_timeline_sources(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    expected_ledger_run_id: str,
    expected_execution_run_id: str,
    protocol_binding_artifact_sha256: str,
    expected_contract_artifact_sha256: str,
    expected_preparation_artifact_sha256: str,
    scientific_execution_authority_artifact_sha256: str,
    expected_output_manifest_artifact_sha256: str,
    generic_ml_projection_artifact_sha256: str,
    confirmatory_timeline_receipt_artifact_sha256: str,
    confirmation_reveal_gate_receipt_artifact_sha256: str,
) -> tuple[
    ScientificConfirmatoryTimelineResolutionStatus,
    str,
    _ScientificConfirmatoryTimelineSources | None,
]:
    binding = require_scientific_confirmatory_protocol_binding(
        registry,
        ledger,
        binding_artifact_sha256=protocol_binding_artifact_sha256,
        expected_ledger_run_id=expected_ledger_run_id,
        expected_execution_run_id=expected_execution_run_id,
    )
    binding_record = registry.get_metadata(protocol_binding_artifact_sha256)
    if (
        binding.contract_artifact_sha256 != expected_contract_artifact_sha256
        or binding.scientific_execution_preparation_artifact_sha256
        != expected_preparation_artifact_sha256
    ):
        raise ScientificPromotionError(
            "scientific confirmatory timeline names another prospective protocol"
        )
    contract_record = registry.get_metadata(expected_contract_artifact_sha256)
    preparation_record = registry.get_metadata(expected_preparation_artifact_sha256)
    _, freeze_value = _load_checked_superiority_artifact(
        registry,
        binding.evaluation_contract_freeze_receipt_artifact_sha256,
        logical_type=EVALUATION_CONTRACT_FREEZE_GATE_RECEIPT_LOGICAL_TYPE,
        creator_role=Role.CLAIM_VERIFIER,
    )
    freeze = EvaluationContractFreezeGateReceipt.from_dict(freeze_value)
    preparation = require_scientific_execution_preparation(
        registry,
        ledger,
        preparation_artifact_sha256=preparation_record.sha256,
        expected_ledger_run_id=expected_ledger_run_id,
        expected_execution_run_id=expected_execution_run_id,
    )
    execution = require_scientific_execution_authority(
        registry,
        ledger,
        authority_artifact_sha256=(
            scientific_execution_authority_artifact_sha256
        ),
        expected_ledger_run_id=expected_ledger_run_id,
        expected_execution_run_id=expected_execution_run_id,
    )
    execution_record = registry.get_metadata(
        scientific_execution_authority_artifact_sha256
    )
    if (
        not execution.scientific_evidence_eligible
        or execution.execution_activity_artifact_sha256 is None
        or execution.preparation_artifact_sha256 != preparation_record.sha256
        or execution.frozen_run_spec_artifact_sha256
        != binding.frozen_run_spec_artifact_sha256
        or execution.output_manifest_artifact_sha256
        != expected_output_manifest_artifact_sha256
    ):
        raise ScientificPromotionError(
            "scientific confirmatory timeline execution is not exact completed v2 authority"
        )
    manifest_record = registry.get_metadata(
        expected_output_manifest_artifact_sha256
    )
    from .generic_ml_projection import (
        require_generic_ml_paired_metric_projection_authority,
    )

    projection_record = registry.get_metadata(
        generic_ml_projection_artifact_sha256
    )
    try:
        projection_value = safe_json_loads(
            registry.get_bytes(projection_record.sha256)
        )
    except (ArtifactError, UnsafeSerializationError, ValidationError) as exc:
        raise ScientificPromotionError(
            "scientific confirmatory paired-metric projection is malformed"
        ) from exc
    if not isinstance(projection_value, Mapping):
        raise ScientificPromotionError(
            "scientific confirmatory paired-metric projection is not an object"
        )
    projection_source_sha256 = _sha256(
        projection_value.get(
            "scientific_domain_evidence_source_artifact_sha256"
        ),
        "scientific confirmatory projection domain source",
    )
    projection = require_generic_ml_paired_metric_projection_authority(
        registry,
        ledger,
        projection_artifact_sha256=projection_record.sha256,
        expected_ledger_run_id=expected_ledger_run_id,
        expected_execution_run_id=expected_execution_run_id,
        expected_domain_evidence_source_artifact_sha256=(
            projection_source_sha256
        ),
        expected_contract_artifact_sha256=contract_record.sha256,
        expected_output_manifest_artifact_sha256=manifest_record.sha256,
    )
    from .experiments import (
        ScientificDatasetAccessPurpose,
        require_scientific_execution_activity,
    )

    activity = require_scientific_execution_activity(
        registry,
        activity_artifact_sha256=execution.execution_activity_artifact_sha256,
        expected_ledger_run_id=expected_ledger_run_id,
        expected_execution_run_id=expected_execution_run_id,
        expected_preparation_artifact_sha256=preparation_record.sha256,
        expected_frozen_run_spec_artifact_sha256=(
            binding.frozen_run_spec_artifact_sha256
        ),
        expected_output_manifest_artifact_sha256=manifest_record.sha256,
    )
    if (
        projection.scientific_execution_authority_artifact_sha256
        != execution_record.sha256
        or projection.scientific_execution_activity_artifact_sha256
        != execution.execution_activity_artifact_sha256
        or projection.evaluation_contract_artifact_sha256
        != contract_record.sha256
        or projection.output_manifest_artifact_sha256 != manifest_record.sha256
        or projection.dataset_authority_artifact_sha256
        != binding.dataset_authority_artifact_sha256
        or tuple(projection.split_authority_artifact_sha256s)
        != binding.split_authority_artifact_sha256s
        or projection.seed_order != binding.seed_order
        or any(
            row.dataset_access_purpose
            is ScientificDatasetAccessPurpose.CONFIRMATORY_LABELS
            for row in activity.activity_rows
        )
    ):
        raise ScientificPromotionError(
            "scientific confirmatory timeline projection or protected access is substituted"
        )

    legacy_record, legacy_value = _load_checked_superiority_artifact(
        registry,
        confirmatory_timeline_receipt_artifact_sha256,
        logical_type=CONFIRMATORY_TIMELINE_RECEIPT_LOGICAL_TYPE,
        creator_role=Role.CLAIM_VERIFIER,
    )
    legacy_unchecked = ConfirmatoryTimelineReceipt.from_dict(legacy_value)
    legacy = require_confirmatory_timeline_receipt(
        registry,
        ledger,
        receipt_artifact_sha256=legacy_record.sha256,
        run_id=expected_ledger_run_id,
        study_id=binding.study_id,
        study_version=binding.study_version,
        protocol_artifact_sha256=binding.protocol_artifact_sha256,
        fresh_custody_receipt_sha256=(
            binding.fresh_custody_receipt_artifact_sha256
        ),
        custody_record_sha256=legacy_unchecked.custody_record_sha256,
        result_artifact_sha256=legacy_unchecked.result_artifact_sha256,
    )
    from .recovery import (
        ConfirmationRevealGateReceipt,
        require_confirmation_reveal_gate_receipt,
    )

    confirmation_record, confirmation_value = _load_checked_superiority_artifact(
        registry,
        confirmation_reveal_gate_receipt_artifact_sha256,
        logical_type="confirmation_reveal_gate_receipt",
        creator_role=Role.CLAIM_VERIFIER,
    )
    confirmation_unchecked = ConfirmationRevealGateReceipt.from_dict(
        confirmation_value
    )
    try:
        confirmation = require_confirmation_reveal_gate_receipt(
            registry,
            ledger,
            receipt_artifact_sha256=confirmation_record.sha256,
            expected_run_id=expected_ledger_run_id,
            expected_object_id=confirmation_unchecked.object_id,
        )
    except Exception as exc:
        if confirmation_unchecked.custody_independence in {
            "HUMAN_INDEPENDENT",
            "SERVICE_INDEPENDENT",
        }:
            return (
                ScientificConfirmatoryTimelineResolutionStatus.BLOCKED_LOCAL,
                "INDEPENDENT_CUSTODY_SOURCE_OWNER_UNSUPPORTED",
                None,
            )
        raise ScientificPromotionError(
            "confirmation reveal receipt failed source-owned replay"
        ) from exc
    if (
        confirmation.fresh_custody_evidence.receipt_artifact_sha256
        != binding.fresh_custody_receipt_artifact_sha256
        or confirmation.fresh_custody_evidence.artifact_record_hash
        != binding.fresh_custody_receipt_record_hash
        or confirmation.reveal_authority.protocol.artifact_sha256
        != binding.protocol_artifact_sha256
        or confirmation.reveal_authority.protocol.artifact_record_hash
        != binding.protocol_record_hash
        or confirmation.started_event_id != legacy.confirmatory_started_event_id
    ):
        raise ScientificPromotionError(
            "independent confirmation receipt names another custody protocol"
        )
    events = ledger.events()
    binding_events = _matching_scientific_confirmatory_protocol_events(
        events,
        binding=binding,
    )
    if len(binding_events) != 1:
        raise ScientificPromotionError(
            "scientific confirmatory protocol publication is absent"
        )
    binding_index, binding_event, _ = binding_events[0]
    custody_index, custody_event = _scientific_confirmatory_custody_freeze_event(
        events,
        run_id=expected_ledger_run_id,
        record=registry.get_metadata(
            binding.fresh_custody_receipt_artifact_sha256
        ),
    )
    if (
        legacy.freeze_event_id != custody_event.event_id
        or legacy.freeze_event_hash != custody_event.event_hash
        or legacy.freeze_event_index != custody_index
    ):
        raise ScientificPromotionError(
            "legacy confirmatory timeline names another custody freeze"
        )
    sources = _ScientificConfirmatoryTimelineSources(
        binding_record=binding_record,
        binding=binding,
        freeze=freeze,
        contract_record=contract_record,
        preparation_record=preparation_record,
        preparation=preparation,
        execution_record=execution_record,
        execution=execution,
        manifest_record=manifest_record,
        projection_record=projection_record,
        projection=projection,
        legacy_timeline_record=legacy_record,
        legacy_timeline=legacy,
        confirmation_record=confirmation_record,
        confirmation=confirmation,
        protocol_binding_event_index=binding_index,
        protocol_binding_event=binding_event,
        custody_freeze_event_index=custody_index,
        custody_freeze_event=custody_event,
    )
    if confirmation.scientific_gate_passed is not True:
        return (
            ScientificConfirmatoryTimelineResolutionStatus.BLOCKED_LOCAL,
            "INDEPENDENT_CUSTODY_PROFILE_NOT_IMPLEMENTED",
            None,
        )
    attestation_hash = confirmation.external_custody_attestation_sha256
    if attestation_hash is None:
        return (
            ScientificConfirmatoryTimelineResolutionStatus.BLOCKED_EXTERNAL,
            "INDEPENDENT_CUSTODY_ATTESTATION_ABSENT",
            None,
        )
    attestation_record = registry.get_metadata(attestation_hash)
    profile_key = (attestation_record.logical_type, attestation_record.schema_version)
    verifier = _SCIENTIFIC_CONFIRMATORY_INDEPENDENT_CUSTODY_VERIFIERS.get(
        profile_key
    )
    if verifier is None:
        return (
            ScientificConfirmatoryTimelineResolutionStatus.BLOCKED_LOCAL,
            "INDEPENDENT_CUSTODY_PROFILE_NOT_IMPLEMENTED",
            None,
        )
    try:
        independently_verified = verifier(
            registry,
            confirmation,
            attestation_record,
        )
    except Exception as exc:  # pragma: no cover - production map is closed-empty
        raise ScientificPromotionError(
            "independent custody verifier failed closed"
        ) from exc
    if independently_verified is not True:  # pragma: no cover - closed-empty map
        raise ScientificPromotionError(
            "independent custody verifier rejected the attestation"
        )
    return ScientificConfirmatoryTimelineResolutionStatus.VERIFIED, "VERIFIED", sources


def _scientific_confirmatory_timeline_receipt_value(
    *,
    receipt_id: str,
    sources: _ScientificConfirmatoryTimelineSources,
    events: tuple[LedgerEvent, ...],
) -> ScientificConfirmatoryTimelineReceiptV2:
    binding = sources.binding
    execution = sources.execution
    projection = sources.projection
    legacy = sources.legacy_timeline
    design_index, design_event = _scientific_confirmatory_live_event(
        events,
        event_id=sources.freeze.design_freeze_event_id,
        event_hash=sources.freeze.design_freeze_event_hash,
    )
    preparation_index, preparation_event = _scientific_confirmatory_live_event(
        events,
        event_id=sources.preparation.ledger_event_id,
        event_hash=sources.preparation.ledger_event_hash,
    )
    custody_index, custody_event = _scientific_confirmatory_live_event(
        events,
        event_id=sources.custody_freeze_event.event_id,
        event_hash=str(sources.custody_freeze_event.event_hash),
    )
    binding_index, binding_event = _scientific_confirmatory_live_event(
        events,
        event_id=sources.protocol_binding_event.event_id,
        event_hash=str(sources.protocol_binding_event.event_hash),
    )
    start_index, start_event = _scientific_confirmatory_live_event(
        events,
        event_id=legacy.confirmatory_started_event_id,
        event_hash=legacy.confirmatory_started_event_hash,
    )
    execution_index, execution_event = _scientific_confirmatory_live_event(
        events,
        event_id=execution.ledger_event_id,
        event_hash=execution.ledger_event_hash,
    )
    reveal_index, reveal_event = _scientific_confirmatory_live_event(
        events,
        event_id=legacy.reveal_event_id,
        event_hash=legacy.reveal_event_hash,
    )
    result_index, result_event = _scientific_confirmatory_live_event(
        events,
        event_id=legacy.result_event_id,
        event_hash=legacy.result_event_hash,
    )
    projection_index, projection_event = _scientific_confirmatory_live_event(
        events,
        event_id=projection.ledger_event_id,
        event_hash=projection.ledger_event_hash,
    )
    if (
        design_index != sources.freeze.design_freeze_event_index
        or preparation_index != sources.preparation.ledger_event_index
        or custody_index != sources.custody_freeze_event_index
        or binding_index != sources.protocol_binding_event_index
        or start_index != legacy.confirmatory_started_event_index
        or execution_index != execution.ledger_event_index
        or reveal_index != legacy.reveal_event_index
        or result_index != legacy.result_event_index
        or projection_index != projection.ledger_event_index
        or any(
            event.run_id != binding.ledger_run_id
            for event in (
                design_event,
                preparation_event,
                custody_event,
                binding_event,
                start_event,
                execution_event,
                reveal_event,
                result_event,
                projection_event,
            )
        )
        or not (
            design_index < preparation_index < binding_index < start_index
            and custody_index < binding_index
            and start_index < execution_index < reveal_index
            and reveal_index <= result_index < projection_index
        )
    ):
        raise ScientificPromotionError(
            "scientific confirmatory source chronology is substituted"
        )
    try:
        completed_at = datetime.fromisoformat(
            execution.attested_completed_at.replace("Z", "+00:00")
        )
        reveal_at = datetime.fromisoformat(
            reveal_event.timestamp.replace("Z", "+00:00")
        )
    except (AttributeError, ValueError) as exc:
        raise ScientificPromotionError(
            "scientific confirmatory execution/reveal timestamp is malformed"
        ) from exc
    if (
        completed_at.utcoffset() is None
        or completed_at.utcoffset().total_seconds() != 0
        or reveal_at.utcoffset() is None
        or reveal_at.utcoffset().total_seconds() != 0
        or completed_at > reveal_at
    ):
        raise ScientificPromotionError(
            "scientific confirmatory outputs were not completed before reveal"
        )
    records = sources.direct_records
    return ScientificConfirmatoryTimelineReceiptV2(
        receipt_id=receipt_id,
        ledger_run_id=binding.ledger_run_id,
        execution_run_id=binding.execution_run_id,
        protocol_binding_artifact_sha256=sources.binding_record.sha256,
        protocol_binding_record_hash=str(sources.binding_record.record_hash),
        contract_artifact_sha256=sources.contract_record.sha256,
        contract_record_hash=str(sources.contract_record.record_hash),
        scientific_execution_preparation_artifact_sha256=(
            sources.preparation_record.sha256
        ),
        scientific_execution_preparation_record_hash=str(
            sources.preparation_record.record_hash
        ),
        scientific_execution_authority_artifact_sha256=(
            sources.execution_record.sha256
        ),
        scientific_execution_authority_record_hash=str(
            sources.execution_record.record_hash
        ),
        output_manifest_artifact_sha256=sources.manifest_record.sha256,
        output_manifest_record_hash=str(sources.manifest_record.record_hash),
        generic_ml_projection_artifact_sha256=sources.projection_record.sha256,
        generic_ml_projection_record_hash=str(
            sources.projection_record.record_hash
        ),
        confirmatory_timeline_receipt_artifact_sha256=(
            sources.legacy_timeline_record.sha256
        ),
        confirmatory_timeline_receipt_record_hash=str(
            sources.legacy_timeline_record.record_hash
        ),
        confirmation_reveal_gate_receipt_artifact_sha256=(
            sources.confirmation_record.sha256
        ),
        confirmation_reveal_gate_receipt_record_hash=str(
            sources.confirmation_record.record_hash
        ),
        direct_source_artifact_sha256s=tuple(item.sha256 for item in records),
        direct_source_artifact_record_hashes=tuple(
            str(item.record_hash) for item in records
        ),
        design_freeze_event_id=design_event.event_id,
        design_freeze_event_hash=str(design_event.event_hash),
        design_freeze_event_index=design_index,
        preparation_event_id=preparation_event.event_id,
        preparation_event_hash=str(preparation_event.event_hash),
        preparation_event_index=preparation_index,
        custody_freeze_event_id=custody_event.event_id,
        custody_freeze_event_hash=str(custody_event.event_hash),
        custody_freeze_event_index=custody_index,
        protocol_binding_event_id=binding_event.event_id,
        protocol_binding_event_hash=str(binding_event.event_hash),
        protocol_binding_event_index=binding_index,
        confirmatory_started_event_id=start_event.event_id,
        confirmatory_started_event_hash=str(start_event.event_hash),
        confirmatory_started_event_index=start_index,
        execution_event_id=execution_event.event_id,
        execution_event_hash=str(execution_event.event_hash),
        execution_event_index=execution_index,
        reveal_event_id=reveal_event.event_id,
        reveal_event_hash=str(reveal_event.event_hash),
        reveal_event_index=reveal_index,
        result_visibility_event_id=result_event.event_id,
        result_visibility_event_hash=str(result_event.event_hash),
        result_visibility_event_index=result_index,
        projection_event_id=projection_event.event_id,
        projection_event_hash=str(projection_event.event_hash),
        projection_event_index=projection_index,
        ledger_prefix_head_hash=str(projection_event.event_hash),
        scientific_gate_passed=True,
    )


def _scientific_confirmatory_timeline_reason(reason_code: str) -> str:
    reasons = {
        "INDEPENDENT_CUSTODY_SOURCE_OWNER_UNSUPPORTED": (
            "the independent-custody receipt has no implemented source-owned replay"
        ),
        "INDEPENDENT_CUSTODY_PROFILE_NOT_IMPLEMENTED": (
            "no reviewed independent-custody verifier profile is implemented locally"
        ),
        "INDEPENDENT_CUSTODY_ATTESTATION_ABSENT": (
            "the supported independent custodian supplied no external attestation"
        ),
    }
    return reasons.get(
        reason_code,
        "the scientific confirmatory timeline is not presently verifiable",
    )


def resolve_scientific_confirmatory_timeline_v2(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    receipt_id: str,
    expected_ledger_run_id: str,
    expected_execution_run_id: str,
    protocol_binding_artifact_sha256: str,
    expected_contract_artifact_sha256: str,
    expected_preparation_artifact_sha256: str,
    scientific_execution_authority_artifact_sha256: str,
    expected_output_manifest_artifact_sha256: str,
    generic_ml_projection_artifact_sha256: str,
    confirmatory_timeline_receipt_artifact_sha256: str,
    confirmation_reveal_gate_receipt_artifact_sha256: str,
) -> ScientificConfirmatoryTimelineResolution:
    """Resolve the v2 chronology without fabricating independent custody.

    Returned blocked states are capability facts.  Malformed, stale, or
    substituted source closures raise instead of becoming ordinary outcomes.
    """

    receipt_id = _identifier(receipt_id, "scientific confirmatory receipt ID")
    expected_ledger_run_id = _identifier(
        expected_ledger_run_id,
        "scientific confirmatory ledger run ID",
    )
    expected_execution_run_id = _identifier(
        expected_execution_run_id,
        "scientific confirmatory execution run ID",
    )
    for value, label in (
        (protocol_binding_artifact_sha256, "protocol binding"),
        (expected_contract_artifact_sha256, "evaluation contract"),
        (expected_preparation_artifact_sha256, "execution preparation"),
        (
            scientific_execution_authority_artifact_sha256,
            "scientific execution authority",
        ),
        (expected_output_manifest_artifact_sha256, "output manifest"),
        (generic_ml_projection_artifact_sha256, "paired-metric projection"),
        (
            confirmatory_timeline_receipt_artifact_sha256,
            "legacy confirmatory timeline",
        ),
        (
            confirmation_reveal_gate_receipt_artifact_sha256,
            "confirmation reveal gate",
        ),
    ):
        _sha256(value, f"scientific confirmatory {label} SHA-256")
    before = _locked_checked_result_authority_snapshot(registry, ledger)
    status, reason_code, sources = _scientific_confirmatory_timeline_sources(
        registry,
        ledger,
        expected_ledger_run_id=expected_ledger_run_id,
        expected_execution_run_id=expected_execution_run_id,
        protocol_binding_artifact_sha256=protocol_binding_artifact_sha256,
        expected_contract_artifact_sha256=expected_contract_artifact_sha256,
        expected_preparation_artifact_sha256=(
            expected_preparation_artifact_sha256
        ),
        scientific_execution_authority_artifact_sha256=(
            scientific_execution_authority_artifact_sha256
        ),
        expected_output_manifest_artifact_sha256=(
            expected_output_manifest_artifact_sha256
        ),
        generic_ml_projection_artifact_sha256=(
            generic_ml_projection_artifact_sha256
        ),
        confirmatory_timeline_receipt_artifact_sha256=(
            confirmatory_timeline_receipt_artifact_sha256
        ),
        confirmation_reveal_gate_receipt_artifact_sha256=(
            confirmation_reveal_gate_receipt_artifact_sha256
        ),
    )
    after = _locked_checked_result_authority_snapshot(registry, ledger)
    if after != before:
        raise ScientificPromotionError(
            "scientific confirmatory sources changed during resolution"
        )
    if status is not ScientificConfirmatoryTimelineResolutionStatus.VERIFIED:
        if sources is not None:
            raise ScientificPromotionError(
                "blocked scientific confirmatory resolution retained sources"
            )
        return ScientificConfirmatoryTimelineResolution(
            status=status,
            reason_code=reason_code,
            reason=_scientific_confirmatory_timeline_reason(reason_code),
        )
    if sources is None:  # pragma: no cover - guarded producer invariant
        raise ScientificPromotionError(
            "verified scientific confirmatory resolution lacks sources"
        )
    receipt = _scientific_confirmatory_timeline_receipt_value(
        receipt_id=receipt_id,
        sources=sources,
        events=before[1].events,
    )
    return ScientificConfirmatoryTimelineResolution(
        status=status,
        reason_code="VERIFIED",
        reason="fresh independent-custody chronology verified",
        receipt=receipt,
    )


def _scientific_confirmatory_timeline_event_binding(
    record: ArtifactRecord,
    receipt: ScientificConfirmatoryTimelineReceiptV2,
) -> dict[str, Any]:
    return {
        "schema_version": SCIENTIFIC_CONFIRMATORY_TIMELINE_EVENT_SCHEMA_V2,
        "kind": "SCIENTIFIC_CONFIRMATORY_TIMELINE_VERIFIED",
        "receipt_id": receipt.receipt_id,
        "ledger_run_id": receipt.ledger_run_id,
        "execution_run_id": receipt.execution_run_id,
        "receipt_artifact_sha256": record.sha256,
        "receipt_record_hash": str(record.record_hash),
        "protocol_binding_artifact_sha256": (
            receipt.protocol_binding_artifact_sha256
        ),
        "scientific_execution_authority_artifact_sha256": (
            receipt.scientific_execution_authority_artifact_sha256
        ),
        "generic_ml_projection_artifact_sha256": (
            receipt.generic_ml_projection_artifact_sha256
        ),
        "source_artifact_sha256s": list(
            receipt.direct_source_artifact_sha256s
        ),
        "source_artifact_record_hashes": list(
            receipt.direct_source_artifact_record_hashes
        ),
        "ledger_prefix_head_hash": receipt.ledger_prefix_head_hash,
        "scientific_gate_passed": True,
    }


def _matching_scientific_confirmatory_timeline_records(
    registry: ArtifactRegistry,
    records: tuple[ArtifactRecord, ...],
    *,
    receipt: ScientificConfirmatoryTimelineReceiptV2,
) -> tuple[tuple[ArtifactRecord, ScientificConfirmatoryTimelineReceiptV2], ...]:
    matches: list[
        tuple[ArtifactRecord, ScientificConfirmatoryTimelineReceiptV2]
    ] = []
    for record in records:
        if record.logical_type != SCIENTIFIC_CONFIRMATORY_TIMELINE_RECEIPT_LOGICAL_TYPE_V2:
            continue
        try:
            value = safe_json_loads(registry.get_bytes(record.sha256))
            candidate = ScientificConfirmatoryTimelineReceiptV2.from_dict(value)
        except (ArtifactError, UnsafeSerializationError, ValidationError) as exc:
            raise ScientificPromotionError(
                "scientific confirmatory timeline artifact slot is malformed"
            ) from exc
        if (
            record.record_hash is None
            or record.origin != _SCIENTIFIC_CONFIRMATORY_TIMELINE_ORIGIN_V2
            or record.creator_role is not Role.CLAIM_VERIFIER
            or record.creation_command != _SCIENTIFIC_CONFIRMATORY_TIMELINE_COMMAND_V2
            or record.schema_version != "2.0"
            or record.mime_type != "application/json"
            or record.validation_result != "PASS"
            or record.frozen is not True
            or record.parent_artifacts
            != candidate.direct_source_artifact_sha256s
            or registry.get_bytes(record.sha256)
            != canonical_json_bytes(candidate.to_dict()) + b"\n"
        ):
            raise ScientificPromotionError(
                "scientific confirmatory timeline artifact is not source-owned"
            )
        if (
            candidate.receipt_id == receipt.receipt_id
            or candidate.execution_run_id == receipt.execution_run_id
            or candidate.protocol_binding_artifact_sha256
            == receipt.protocol_binding_artifact_sha256
            or candidate.scientific_execution_authority_artifact_sha256
            == receipt.scientific_execution_authority_artifact_sha256
            or candidate.generic_ml_projection_artifact_sha256
            == receipt.generic_ml_projection_artifact_sha256
        ):
            matches.append((record, candidate))
    if len(matches) > 1:
        raise ScientificPromotionError(
            "scientific confirmatory timeline artifact slot is ambiguous"
        )
    return tuple(matches)


def _matching_scientific_confirmatory_timeline_events(
    events: tuple[LedgerEvent, ...],
    *,
    receipt: ScientificConfirmatoryTimelineReceiptV2,
) -> tuple[tuple[int, LedgerEvent, Mapping[str, Any]], ...]:
    matches: list[tuple[int, LedgerEvent, Mapping[str, Any]]] = []
    for index, event in enumerate(events):
        candidate = _event_metadata_value(event).get(
            "scientific_confirmatory_timeline"
        )
        if not isinstance(candidate, Mapping):
            continue
        if (
            candidate.get("receipt_id") == receipt.receipt_id
            or candidate.get("execution_run_id") == receipt.execution_run_id
            or candidate.get("protocol_binding_artifact_sha256")
            == receipt.protocol_binding_artifact_sha256
            or candidate.get("scientific_execution_authority_artifact_sha256")
            == receipt.scientific_execution_authority_artifact_sha256
            or candidate.get("generic_ml_projection_artifact_sha256")
            == receipt.generic_ml_projection_artifact_sha256
        ):
            matches.append((index, event, candidate))
    if len(matches) > 1:
        raise ScientificPromotionError(
            "scientific confirmatory timeline publication slot is ambiguous"
        )
    return tuple(matches)


def _validate_scientific_confirmatory_timeline_event(
    event: LedgerEvent,
    event_index: int,
    events: tuple[LedgerEvent, ...],
    *,
    record: ArtifactRecord,
    receipt: ScientificConfirmatoryTimelineReceiptV2,
    source_records: tuple[ArtifactRecord, ...],
) -> None:
    binding = _scientific_confirmatory_timeline_event_binding(record, receipt)
    records = (record, *source_records)
    metadata = _event_metadata_value(event)
    try:
        event_time = datetime.fromisoformat(
            event.timestamp.replace("Z", "+00:00")
        )
        record_times = tuple(
            datetime.fromisoformat(item.created_at.replace("Z", "+00:00"))
            for item in records
        )
    except (AttributeError, ValueError) as exc:
        raise ScientificPromotionError(
            "scientific confirmatory publication timestamp is malformed"
        ) from exc
    if (
        event.event_hash is None
        or event_time.utcoffset() is None
        or event_time.utcoffset().total_seconds() != 0
        or any(
            value.utcoffset() is None
            or value.utcoffset().total_seconds() != 0
            or event_time < value
            for value in record_times
        )
        or event.run_id != receipt.ledger_run_id
        or event.actor_role is not Role.CLAIM_VERIFIER
        or event.event_type != "CHECKPOINT"
        or event.state_before != event.state_after
        or event.artifact_hashes != tuple(item.sha256 for item in records)
        or event.code_version != SCIENTIFIC_CONFIRMATORY_TIMELINE_EVENT_SCHEMA_V2
        or event.configuration_hash != _canonical_hash(binding)
        or event.dataset_identifiers
        != (
            receipt.protocol_binding_artifact_sha256,
            receipt.output_manifest_artifact_sha256,
        )
        or event.random_seeds
        or event.evaluator_outputs
        or event.reason
        != "published independently verified scientific confirmatory chronology"
        or set(metadata)
        != {
            "artifact_types",
            "artifact_record_hashes",
            "scientific_confirmatory_timeline",
        }
        or metadata["artifact_types"]
        != [item.logical_type for item in records]
        or metadata["artifact_record_hashes"]
        != [str(item.record_hash) for item in records]
        or metadata["scientific_confirmatory_timeline"] != binding
        or event_index <= receipt.projection_event_index
        or any(
            later.event_type == "CORRECTION"
            and later.supersedes_event_id == event.event_id
            for later in events[event_index + 1 :]
        )
    ):
        raise ScientificPromotionError(
            "scientific confirmatory timeline publication is substituted or stale"
        )


def register_scientific_confirmatory_timeline_receipt_v2(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    receipt_id: str,
    expected_ledger_run_id: str,
    expected_execution_run_id: str,
    protocol_binding_artifact_sha256: str,
    expected_contract_artifact_sha256: str,
    expected_preparation_artifact_sha256: str,
    scientific_execution_authority_artifact_sha256: str,
    expected_output_manifest_artifact_sha256: str,
    generic_ml_projection_artifact_sha256: str,
    confirmatory_timeline_receipt_artifact_sha256: str,
    confirmation_reveal_gate_receipt_artifact_sha256: str,
) -> ArtifactRecord:
    """Publish a v2 receipt only after a positive independent-custody replay."""

    before = _locked_checked_result_authority_snapshot(
        registry,
        ledger,
        ensure_storage=True,
    )
    resolution = resolve_scientific_confirmatory_timeline_v2(
        registry,
        ledger,
        receipt_id=receipt_id,
        expected_ledger_run_id=expected_ledger_run_id,
        expected_execution_run_id=expected_execution_run_id,
        protocol_binding_artifact_sha256=protocol_binding_artifact_sha256,
        expected_contract_artifact_sha256=expected_contract_artifact_sha256,
        expected_preparation_artifact_sha256=(
            expected_preparation_artifact_sha256
        ),
        scientific_execution_authority_artifact_sha256=(
            scientific_execution_authority_artifact_sha256
        ),
        expected_output_manifest_artifact_sha256=(
            expected_output_manifest_artifact_sha256
        ),
        generic_ml_projection_artifact_sha256=(
            generic_ml_projection_artifact_sha256
        ),
        confirmatory_timeline_receipt_artifact_sha256=(
            confirmatory_timeline_receipt_artifact_sha256
        ),
        confirmation_reveal_gate_receipt_artifact_sha256=(
            confirmation_reveal_gate_receipt_artifact_sha256
        ),
    )
    if resolution.status is not ScientificConfirmatoryTimelineResolutionStatus.VERIFIED:
        raise ScientificConfirmatoryTimelineUnavailable(
            resolution.status,
            resolution.reason_code,
            resolution.reason,
        )
    receipt = resolution.receipt
    if receipt is None:  # pragma: no cover - resolution invariant
        raise ScientificPromotionError(
            "verified scientific confirmatory timeline lacks a receipt"
        )
    after_resolution = _locked_checked_result_authority_snapshot(registry, ledger)
    if after_resolution != before:
        raise ScientificPromotionError(
            "scientific confirmatory sources changed before publication"
        )
    data = canonical_json_bytes(receipt.to_dict()) + b"\n"
    if len(data) > MAX_ARTIFACT_OBJECT_BYTES:
        raise ScientificPromotionError(
            "scientific confirmatory timeline exceeds registry object capacity"
        )
    digest = hashlib.sha256(data).hexdigest()
    matches = _matching_scientific_confirmatory_timeline_records(
        registry,
        before[0].records,
        receipt=receipt,
    )
    record: ArtifactRecord | None = None
    if matches:
        record, existing = matches[0]
        if record.sha256 != digest or existing != receipt:
            raise ScientificPromotionError(
                "scientific confirmatory timeline slot has a competing receipt"
            )
    prior_events = _matching_scientific_confirmatory_timeline_events(
        before[1].events,
        receipt=receipt,
    )
    if prior_events and record is None:
        raise ScientificPromotionError(
            "scientific confirmatory publication names an absent receipt"
        )
    missing_record = int(record is None)
    missing_event = int(not prior_events)
    if before[0].count + missing_record > MAX_REGISTRY_RECORDS:
        raise ScientificPromotionError(
            "scientific confirmatory timeline exceeds registry capacity"
        )
    if before[1].event_count + missing_event > MAX_LEDGER_EVENTS:
        raise ScientificPromotionError(
            "scientific confirmatory timeline exceeds ledger event capacity"
        )
    if (
        missing_event
        and before[1].valid_prefix_bytes
        + _MAX_SCIENTIFIC_CONFIRMATORY_EVENT_BYTES
        > MAX_LEDGER_BYTES
    ):
        raise ScientificPromotionError(
            "scientific confirmatory timeline exceeds ledger byte capacity"
        )
    registry_guard = registry._open_mutation_lock()
    try:
        ledger_guard = ledger._open_lock()
        try:
            locked_registry = registry._verify_all_locked(
                registry_guard,
                raise_on_error=True,
            )
            locked_ledger = ledger._validate_bytes(
                ledger._read_raw_locked(ledger_guard)
            )
            if (
                not locked_ledger.valid
                or locked_registry != before[0]
                or locked_ledger != before[1]
            ):
                raise ScientificPromotionError(
                    "scientific confirmatory sources changed before commit; retry"
                )
            if record is None:
                record = registry._put_bytes_locked(
                    registry_guard,
                    data,
                    logical_type=(
                        SCIENTIFIC_CONFIRMATORY_TIMELINE_RECEIPT_LOGICAL_TYPE_V2
                    ),
                    origin=_SCIENTIFIC_CONFIRMATORY_TIMELINE_ORIGIN_V2,
                    creator_role=Role.CLAIM_VERIFIER,
                    creation_command=_SCIENTIFIC_CONFIRMATORY_TIMELINE_COMMAND_V2,
                    parent_artifacts=receipt.direct_source_artifact_sha256s,
                    schema_version="2.0",
                    mime_type="application/json",
                    validation_result="PASS",
                    frozen=True,
                    created_at=None,
                )
                if record.sha256 != digest:
                    raise ScientificPromotionError(
                        "scientific confirmatory receipt changed during materialization"
                    )
            source_records = tuple(
                registry.get_metadata(item)
                for item in receipt.direct_source_artifact_sha256s
            )
            binding = _scientific_confirmatory_timeline_event_binding(
                record,
                receipt,
            )
            resolved = _matching_scientific_confirmatory_timeline_events(
                locked_ledger.events,
                receipt=receipt,
            )
            if resolved:
                event_index, event, candidate = resolved[0]
                if dict(candidate) != binding:
                    raise ScientificPromotionError(
                        "scientific confirmatory publication is competing"
                    )
            else:
                state = _timeline_state(locked_ledger.events)
                event = LedgerEvent.create(
                    run_id=receipt.ledger_run_id,
                    actor_role=Role.CLAIM_VERIFIER,
                    state_before=state,
                    requested_state_after=state,
                    artifact_hashes=(
                        record.sha256,
                        *(item.sha256 for item in source_records),
                    ),
                    code_version=SCIENTIFIC_CONFIRMATORY_TIMELINE_EVENT_SCHEMA_V2,
                    configuration_hash=_canonical_hash(binding),
                    dataset_identifiers=(
                        receipt.protocol_binding_artifact_sha256,
                        receipt.output_manifest_artifact_sha256,
                    ),
                    random_seeds=(),
                    evaluator_outputs=(),
                    reason=(
                        "published independently verified scientific "
                        "confirmatory chronology"
                    ),
                    prior_event_hash=locked_ledger.head_hash,
                    event_type="CHECKPOINT",
                    metadata={
                        "artifact_types": [
                            record.logical_type,
                            *(item.logical_type for item in source_records),
                        ],
                        "artifact_record_hashes": [
                            str(record.record_hash),
                            *(str(item.record_hash) for item in source_records),
                        ],
                        "scientific_confirmatory_timeline": binding,
                    },
                )
                encoded_event = canonical_json_bytes(event.to_dict()) + b"\n"
                if (
                    len(encoded_event) > _MAX_SCIENTIFIC_CONFIRMATORY_EVENT_BYTES
                    or locked_ledger.valid_prefix_bytes + len(encoded_event)
                    > MAX_LEDGER_BYTES
                ):
                    raise ScientificPromotionError(
                        "scientific confirmatory publication exceeds its preflight"
                    )

                def build(current: LedgerValidationResult) -> LedgerEvent:
                    if current != locked_ledger:
                        raise ScientificPromotionError(
                            "scientific confirmatory ledger changed during commit"
                        )
                    return event

                event = ledger._append_locked(ledger_guard, build)
                event_index = len(locked_ledger.events)
            committed_registry = registry._verify_all_locked(
                registry_guard,
                raise_on_error=True,
            )
            committed_ledger = ledger._validate_bytes(
                ledger._read_raw_locked(ledger_guard)
            )
            committed_matches = _matching_scientific_confirmatory_timeline_records(
                registry,
                committed_registry.records,
                receipt=receipt,
            )
            committed_events = _matching_scientific_confirmatory_timeline_events(
                committed_ledger.events,
                receipt=receipt,
            )
            if (
                not committed_ledger.valid
                or committed_registry.count != before[0].count + missing_record
                or committed_ledger.event_count
                != before[1].event_count + missing_event
                or committed_matches != ((record, receipt),)
                or len(committed_events) != 1
                or committed_events[0][:2] != (event_index, event)
            ):
                raise ScientificPromotionError(
                    "scientific confirmatory timeline commit is incomplete"
                )
            _validate_scientific_confirmatory_timeline_event(
                event,
                event_index,
                committed_ledger.events,
                record=record,
                receipt=receipt,
                source_records=source_records,
            )
            registry._verify_mutation_namespace(registry_guard)
        finally:
            ledger._unlock(ledger_guard)
    finally:
        registry._unlock_mutation(registry_guard)
    assert record is not None
    require_scientific_confirmatory_timeline_receipt_v2(
        registry,
        ledger,
        receipt_artifact_sha256=record.sha256,
        expected_ledger_run_id=expected_ledger_run_id,
        expected_execution_run_id=expected_execution_run_id,
        expected_contract_artifact_sha256=expected_contract_artifact_sha256,
        expected_preparation_artifact_sha256=(
            expected_preparation_artifact_sha256
        ),
        expected_execution_authority_artifact_sha256=(
            scientific_execution_authority_artifact_sha256
        ),
        expected_output_manifest_artifact_sha256=(
            expected_output_manifest_artifact_sha256
        ),
        expected_generic_ml_projection_artifact_sha256=(
            generic_ml_projection_artifact_sha256
        ),
    )
    return record


@dataclass(frozen=True, slots=True)
class _ScientificConfirmatoryTimelineReplayV2:
    """Validated publication and source snapshot from one timeline replay."""

    receipt: ScientificConfirmatoryTimelineReceiptV2
    record: ArtifactRecord
    publication_event_id: str
    publication_event_hash: str
    publication_event_index: int
    entry_snapshot: tuple[RegistryValidationResult, LedgerValidationResult]
    protocol_binding: ScientificConfirmatoryProtocolBinding

    def __post_init__(self) -> None:
        if type(self.receipt) is not ScientificConfirmatoryTimelineReceiptV2:
            raise ScientificPromotionError(
                "scientific confirmatory timeline replay lacks its receipt"
            )
        if type(self.record) is not ArtifactRecord:
            raise ScientificPromotionError(
                "scientific confirmatory timeline replay lacks its artifact record"
            )
        if type(self.protocol_binding) is not ScientificConfirmatoryProtocolBinding:
            raise ScientificPromotionError(
                "scientific confirmatory timeline replay lacks its protocol binding"
            )
        if (
            type(self.publication_event_id) is not str
            or type(self.publication_event_hash) is not str
            or type(self.publication_event_index) is not int
            or self.publication_event_index < 0
            or type(self.entry_snapshot) is not tuple
            or len(self.entry_snapshot) != 2
            or type(self.entry_snapshot[0]) is not RegistryValidationResult
            or type(self.entry_snapshot[1]) is not LedgerValidationResult
        ):
            raise ScientificPromotionError(
                "scientific confirmatory timeline replay snapshot is malformed"
            )


def _require_scientific_confirmatory_timeline_source_v2(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    receipt_artifact_sha256: str,
    expected_ledger_run_id: str,
    expected_execution_run_id: str,
    expected_contract_artifact_sha256: str,
    expected_preparation_artifact_sha256: str,
    expected_execution_authority_artifact_sha256: str,
    expected_output_manifest_artifact_sha256: str,
    expected_generic_ml_projection_artifact_sha256: str,
) -> _ScientificConfirmatoryTimelineReplayV2:
    """Freshly replay one registered positive v2 scientific chronology."""

    before = _locked_checked_result_authority_snapshot(registry, ledger)
    record, value = _load_checked_superiority_artifact(
        registry,
        receipt_artifact_sha256,
        logical_type=SCIENTIFIC_CONFIRMATORY_TIMELINE_RECEIPT_LOGICAL_TYPE_V2,
        creator_role=Role.CLAIM_VERIFIER,
    )
    receipt = ScientificConfirmatoryTimelineReceiptV2.from_dict(value)
    if (
        record.origin != _SCIENTIFIC_CONFIRMATORY_TIMELINE_ORIGIN_V2
        or record.creation_command != _SCIENTIFIC_CONFIRMATORY_TIMELINE_COMMAND_V2
        or record.schema_version != "2.0"
        or record.parent_artifacts != receipt.direct_source_artifact_sha256s
        or receipt.ledger_run_id != expected_ledger_run_id
        or receipt.execution_run_id != expected_execution_run_id
        or receipt.contract_artifact_sha256
        != expected_contract_artifact_sha256
        or receipt.scientific_execution_preparation_artifact_sha256
        != expected_preparation_artifact_sha256
        or receipt.scientific_execution_authority_artifact_sha256
        != expected_execution_authority_artifact_sha256
        or receipt.output_manifest_artifact_sha256
        != expected_output_manifest_artifact_sha256
        or receipt.generic_ml_projection_artifact_sha256
        != expected_generic_ml_projection_artifact_sha256
    ):
        raise ScientificPromotionError(
            "scientific confirmatory timeline names another source closure"
        )
    status, reason_code, sources = _scientific_confirmatory_timeline_sources(
        registry,
        ledger,
        expected_ledger_run_id=expected_ledger_run_id,
        expected_execution_run_id=expected_execution_run_id,
        protocol_binding_artifact_sha256=(
            receipt.protocol_binding_artifact_sha256
        ),
        expected_contract_artifact_sha256=expected_contract_artifact_sha256,
        expected_preparation_artifact_sha256=(
            expected_preparation_artifact_sha256
        ),
        scientific_execution_authority_artifact_sha256=(
            expected_execution_authority_artifact_sha256
        ),
        expected_output_manifest_artifact_sha256=(
            expected_output_manifest_artifact_sha256
        ),
        generic_ml_projection_artifact_sha256=(
            expected_generic_ml_projection_artifact_sha256
        ),
        confirmatory_timeline_receipt_artifact_sha256=(
            receipt.confirmatory_timeline_receipt_artifact_sha256
        ),
        confirmation_reveal_gate_receipt_artifact_sha256=(
            receipt.confirmation_reveal_gate_receipt_artifact_sha256
        ),
    )
    if status is not ScientificConfirmatoryTimelineResolutionStatus.VERIFIED:
        raise ScientificConfirmatoryTimelineUnavailable(
            status,
            reason_code,
            _scientific_confirmatory_timeline_reason(reason_code),
        )
    if sources is None:  # pragma: no cover - resolution invariant
        raise ScientificPromotionError(
            "verified scientific confirmatory replay lacks its sources"
        )
    expected = _scientific_confirmatory_timeline_receipt_value(
        receipt_id=receipt.receipt_id,
        sources=sources,
        events=before[1].events,
    )
    if receipt != expected:
        raise ScientificPromotionError(
            "scientific confirmatory timeline differs from fresh source replay"
        )
    matches = _matching_scientific_confirmatory_timeline_records(
        registry,
        before[0].records,
        receipt=receipt,
    )
    if matches != ((record, receipt),):
        raise ScientificPromotionError(
            "scientific confirmatory timeline artifact slot is ambiguous"
        )
    events = _matching_scientific_confirmatory_timeline_events(
        before[1].events,
        receipt=receipt,
    )
    if len(events) != 1:
        raise ScientificPromotionError(
            "scientific confirmatory timeline lacks one publication"
        )
    event_index, event, candidate = events[0]
    if dict(candidate) != _scientific_confirmatory_timeline_event_binding(
        record,
        receipt,
    ):
        raise ScientificPromotionError(
            "scientific confirmatory timeline publication is competing"
        )
    _validate_scientific_confirmatory_timeline_event(
        event,
        event_index,
        before[1].events,
        record=record,
        receipt=receipt,
        source_records=sources.direct_records,
    )
    after = _locked_checked_result_authority_snapshot(registry, ledger)
    if after != before:
        raise ScientificPromotionError(
            "scientific confirmatory timeline sources changed during replay"
        )
    return _ScientificConfirmatoryTimelineReplayV2(
        receipt=receipt,
        record=record,
        publication_event_id=event.event_id,
        publication_event_hash=event.event_hash,
        publication_event_index=event_index,
        entry_snapshot=before,
        protocol_binding=sources.binding,
    )


def require_scientific_confirmatory_timeline_receipt_v2(
    registry: ArtifactRegistry,
    ledger: EventLedger,
    *,
    receipt_artifact_sha256: str,
    expected_ledger_run_id: str,
    expected_execution_run_id: str,
    expected_contract_artifact_sha256: str,
    expected_preparation_artifact_sha256: str,
    expected_execution_authority_artifact_sha256: str,
    expected_output_manifest_artifact_sha256: str,
    expected_generic_ml_projection_artifact_sha256: str,
) -> ScientificConfirmatoryTimelineReceiptV2:
    """Freshly replay one registered positive v2 scientific chronology."""

    return _require_scientific_confirmatory_timeline_source_v2(
        registry,
        ledger,
        receipt_artifact_sha256=receipt_artifact_sha256,
        expected_ledger_run_id=expected_ledger_run_id,
        expected_execution_run_id=expected_execution_run_id,
        expected_contract_artifact_sha256=expected_contract_artifact_sha256,
        expected_preparation_artifact_sha256=expected_preparation_artifact_sha256,
        expected_execution_authority_artifact_sha256=(
            expected_execution_authority_artifact_sha256
        ),
        expected_output_manifest_artifact_sha256=(
            expected_output_manifest_artifact_sha256
        ),
        expected_generic_ml_projection_artifact_sha256=(
            expected_generic_ml_projection_artifact_sha256
        ),
    ).receipt


@dataclass(frozen=True, slots=True)
class CheckedSuperiorityPromotion:
    """Content-bound receipt derived from immutable registered scientific inputs."""

    receipt_id: str
    contract_artifact_sha256: str
    contract_sha256: str
    evidence_eligibility_sha256: str
    aggregate_result_sha256: str
    statistical_analysis_sha256: str
    evaluator_assessment_sha256: str
    scientific_obligations_sha256: str
    proxy_inference_verification_sha256: str | None
    baseline_exclusion_receipt_sha256s: tuple[str, ...]
    contract_record_hash: str
    eligibility_record_hash: str
    aggregate_record_hash: str
    statistical_record_hash: str
    evaluator_record_hash: str
    metric_id: str
    metric_unit: MetricUnit
    claimed_scope: MetricScope
    baseline_id: str
    candidate_value: float
    baseline_value: float
    improvement_effect: float
    confidence_low: float
    confidence_high: float
    adjusted_p_value: float
    sample_size: int
    evaluator_id: str
    evaluator_version: str
    scientific_evidence_eligible: bool
    status: SuperiorityValidationStatus = (
        SuperiorityValidationStatus.SCIENTIFIC_PROMOTION_AUTHORIZED
    )

    def __post_init__(self) -> None:
        object.__setattr__(self, "receipt_id", _identifier(self.receipt_id, "receipt_id"))
        for name in (
            "contract_artifact_sha256",
            "contract_sha256",
            "evidence_eligibility_sha256",
            "aggregate_result_sha256",
            "statistical_analysis_sha256",
            "evaluator_assessment_sha256",
            "scientific_obligations_sha256",
            "contract_record_hash",
            "eligibility_record_hash",
            "aggregate_record_hash",
            "statistical_record_hash",
            "evaluator_record_hash",
        ):
            object.__setattr__(self, name, _sha256(getattr(self, name), name))
        if self.proxy_inference_verification_sha256 is not None:
            object.__setattr__(
                self,
                "proxy_inference_verification_sha256",
                _sha256(
                    self.proxy_inference_verification_sha256,
                    "proxy_inference_verification_sha256",
                ),
            )
        exclusions = _identifiers(
            self.baseline_exclusion_receipt_sha256s,
            "baseline_exclusion_receipt_sha256s",
            allow_empty=True,
        )
        if any(len(value) != 64 for value in exclusions):
            raise ScientificDesignError(
                "baseline exclusion receipt identities must be SHA-256 hashes"
            )
        object.__setattr__(self, "baseline_exclusion_receipt_sha256s", exclusions)
        object.__setattr__(self, "metric_id", _identifier(self.metric_id, "metric_id"))
        _enum(self, "metric_unit", MetricUnit)
        _enum(self, "claimed_scope", MetricScope)
        object.__setattr__(self, "baseline_id", _identifier(self.baseline_id, "baseline_id"))
        for name in (
            "candidate_value",
            "baseline_value",
            "improvement_effect",
            "confidence_low",
            "confidence_high",
            "adjusted_p_value",
        ):
            object.__setattr__(self, name, _finite(getattr(self, name), name))
        if self.confidence_low > self.confidence_high:
            raise ScientificDesignError("checked superiority confidence bounds are reversed")
        if not 0.0 <= self.adjusted_p_value <= 1.0:
            raise ScientificDesignError("checked superiority p-value is outside [0, 1]")
        _positive_int(self.sample_size, "sample_size")
        object.__setattr__(
            self,
            "evaluator_id",
            _identifier(self.evaluator_id, "evaluator_id"),
        )
        object.__setattr__(
            self,
            "evaluator_version",
            _text(self.evaluator_version, "evaluator_version"),
        )
        if self.scientific_evidence_eligible is not True:
            raise ScientificPromotionError(
                "checked superiority authority requires scientifically eligible evidence"
            )
        _enum(self, "status", SuperiorityValidationStatus)
        if self.status is not SuperiorityValidationStatus.SCIENTIFIC_PROMOTION_AUTHORIZED:
            raise ScientificDesignError("checked superiority receipt has no promotion authority")

    @property
    def authoritative(self) -> bool:
        return True

    @property
    def source_artifact_hashes(self) -> tuple[str, ...]:
        return (
            self.contract_artifact_sha256,
            self.evidence_eligibility_sha256,
            self.aggregate_result_sha256,
            self.statistical_analysis_sha256,
            self.evaluator_assessment_sha256,
            self.scientific_obligations_sha256,
            *(
                (self.proxy_inference_verification_sha256,)
                if self.proxy_inference_verification_sha256 is not None
                else ()
            ),
            *self.baseline_exclusion_receipt_sha256s,
        )

    def to_dict(self) -> dict[str, Any]:
        return {
            "schema_version": CHECKED_SUPERIORITY_RECEIPT_SCHEMA,
            "receipt_id": self.receipt_id,
            "contract_artifact_sha256": self.contract_artifact_sha256,
            "contract_sha256": self.contract_sha256,
            "evidence_eligibility_sha256": self.evidence_eligibility_sha256,
            "aggregate_result_sha256": self.aggregate_result_sha256,
            "statistical_analysis_sha256": self.statistical_analysis_sha256,
            "evaluator_assessment_sha256": self.evaluator_assessment_sha256,
            "scientific_obligations_sha256": self.scientific_obligations_sha256,
            "proxy_inference_verification_sha256": (
                self.proxy_inference_verification_sha256
            ),
            "baseline_exclusion_receipt_sha256s": list(
                self.baseline_exclusion_receipt_sha256s
            ),
            "contract_record_hash": self.contract_record_hash,
            "eligibility_record_hash": self.eligibility_record_hash,
            "aggregate_record_hash": self.aggregate_record_hash,
            "statistical_record_hash": self.statistical_record_hash,
            "evaluator_record_hash": self.evaluator_record_hash,
            "metric_id": self.metric_id,
            "metric_unit": self.metric_unit.value,
            "claimed_scope": self.claimed_scope.value,
            "baseline_id": self.baseline_id,
            "candidate_value": self.candidate_value,
            "baseline_value": self.baseline_value,
            "improvement_effect": self.improvement_effect,
            "confidence_low": self.confidence_low,
            "confidence_high": self.confidence_high,
            "adjusted_p_value": self.adjusted_p_value,
            "sample_size": self.sample_size,
            "evaluator_id": self.evaluator_id,
            "evaluator_version": self.evaluator_version,
            "scientific_evidence_eligible": self.scientific_evidence_eligible,
            "status": self.status.value,
        }

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> CheckedSuperiorityPromotion:
        _require_exact_keys(
            value,
            {
                "schema_version",
                "receipt_id",
                "contract_artifact_sha256",
                "contract_sha256",
                "evidence_eligibility_sha256",
                "aggregate_result_sha256",
                "statistical_analysis_sha256",
                "evaluator_assessment_sha256",
                "scientific_obligations_sha256",
                "proxy_inference_verification_sha256",
                "baseline_exclusion_receipt_sha256s",
                "contract_record_hash",
                "eligibility_record_hash",
                "aggregate_record_hash",
                "statistical_record_hash",
                "evaluator_record_hash",
                "metric_id",
                "metric_unit",
                "claimed_scope",
                "baseline_id",
                "candidate_value",
                "baseline_value",
                "improvement_effect",
                "confidence_low",
                "confidence_high",
                "adjusted_p_value",
                "sample_size",
                "evaluator_id",
                "evaluator_version",
                "scientific_evidence_eligible",
                "status",
            },
            "checked superiority receipt",
        )
        if value["schema_version"] != CHECKED_SUPERIORITY_RECEIPT_SCHEMA:
            raise ScientificPromotionError("unsupported checked superiority receipt schema")
        try:
            return cls(
                receipt_id=value["receipt_id"],
                contract_artifact_sha256=value["contract_artifact_sha256"],
                contract_sha256=value["contract_sha256"],
                evidence_eligibility_sha256=value["evidence_eligibility_sha256"],
                aggregate_result_sha256=value["aggregate_result_sha256"],
                statistical_analysis_sha256=value["statistical_analysis_sha256"],
                evaluator_assessment_sha256=value["evaluator_assessment_sha256"],
                scientific_obligations_sha256=value["scientific_obligations_sha256"],
                proxy_inference_verification_sha256=value[
                    "proxy_inference_verification_sha256"
                ],
                baseline_exclusion_receipt_sha256s=tuple(
                    value["baseline_exclusion_receipt_sha256s"]
                ),
                contract_record_hash=value["contract_record_hash"],
                eligibility_record_hash=value["eligibility_record_hash"],
                aggregate_record_hash=value["aggregate_record_hash"],
                statistical_record_hash=value["statistical_record_hash"],
                evaluator_record_hash=value["evaluator_record_hash"],
                metric_id=value["metric_id"],
                metric_unit=MetricUnit(value["metric_unit"]),
                claimed_scope=MetricScope(value["claimed_scope"]),
                baseline_id=value["baseline_id"],
                candidate_value=value["candidate_value"],
                baseline_value=value["baseline_value"],
                improvement_effect=value["improvement_effect"],
                confidence_low=value["confidence_low"],
                confidence_high=value["confidence_high"],
                adjusted_p_value=value["adjusted_p_value"],
                sample_size=value["sample_size"],
                evaluator_id=value["evaluator_id"],
                evaluator_version=value["evaluator_version"],
                scientific_evidence_eligible=value["scientific_evidence_eligible"],
                status=SuperiorityValidationStatus(value["status"]),
            )
        except (KeyError, TypeError, ValueError) as exc:
            raise ScientificPromotionError("checked superiority receipt is malformed") from exc


@dataclass(frozen=True, slots=True)
class CheckedResultAssessment:
    """Outcome-neutral facts authorized by one exact scientific execution."""

    assessment_id: str
    ledger_run_id: str
    execution_run_id: str
    hypothesis_id: str
    contract_artifact_sha256: str
    contract_sha256: str
    contract_record_hash: str
    scientific_execution_authority_artifact_sha256: str
    scientific_execution_authority_record_hash: str
    frozen_run_spec_artifact_sha256: str
    output_manifest_artifact_sha256: str
    aggregate_result_sha256: str
    aggregate_record_hash: str
    statistical_analysis_sha256: str
    statistical_record_hash: str
    evaluator_assessment_sha256: str | None
    evaluator_record_hash: str | None
    scientific_obligations_sha256: str | None
    obligations_record_hash: str | None
    baseline_exclusion_receipt_sha256s: tuple[str, ...]
    baseline_exclusion_receipt_record_hashes: tuple[str, ...]
    metric_id: str
    metric_unit: MetricUnit
    metric_scope: MetricScope
    baseline_id: str
    candidate_value: float
    baseline_value: float
    improvement_effect: float
    confidence_low: float
    confidence_high: float
    adjusted_p_value: float | None
    sample_size: int
    hypothesis_status: HypothesisStatus
    outcome: ScientificResultOutcome
    scientific_evidence_eligible: bool
    generic_ml_paired_metric_projection_authority_artifact_sha256: str | None = None
    generic_ml_paired_metric_projection_authority_record_hash: str | None = None
    scientific_execution_admissibility_authority_artifact_sha256: str | None = None
    scientific_execution_admissibility_authority_record_hash: str | None = None
    domain_validity_receipt_artifact_sha256: str | None = None
    domain_validity_receipt_record_hash: str | None = None
    statistical_use_authority_artifact_sha256: str | None = None
    statistical_use_authority_record_hash: str | None = None
    inference_profile_id: str | None = None
    mean_zero_p_upper: float | None = None

    def __post_init__(self) -> None:
        for name in (
            "assessment_id",
            "ledger_run_id",
            "execution_run_id",
            "hypothesis_id",
            "metric_id",
            "baseline_id",
        ):
            object.__setattr__(self, name, _identifier(getattr(self, name), name))
        for name in (
            "contract_artifact_sha256",
            "contract_sha256",
            "contract_record_hash",
            "scientific_execution_authority_artifact_sha256",
            "scientific_execution_authority_record_hash",
            "frozen_run_spec_artifact_sha256",
            "output_manifest_artifact_sha256",
            "aggregate_result_sha256",
            "aggregate_record_hash",
            "statistical_analysis_sha256",
            "statistical_record_hash",
        ):
            object.__setattr__(self, name, _sha256(getattr(self, name), name))
        legacy_names = (
            "evaluator_assessment_sha256",
            "evaluator_record_hash",
            "scientific_obligations_sha256",
            "obligations_record_hash",
        )
        projection_names = (
            "generic_ml_paired_metric_projection_authority_artifact_sha256",
            "generic_ml_paired_metric_projection_authority_record_hash",
            "scientific_execution_admissibility_authority_artifact_sha256",
            "scientific_execution_admissibility_authority_record_hash",
            "domain_validity_receipt_artifact_sha256",
            "domain_validity_receipt_record_hash",
        )
        legacy_present = tuple(getattr(self, name) is not None for name in legacy_names)
        projection_present = tuple(
            getattr(self, name) is not None for name in projection_names
        )
        if (all(legacy_present) and not any(projection_present)):
            selected_names = legacy_names
        elif (not any(legacy_present) and all(projection_present)):
            selected_names = projection_names
        else:
            raise ScientificPromotionError(
                "checked result assessment must use exactly one source-owner version"
            )
        for name in selected_names:
            object.__setattr__(self, name, _sha256(getattr(self, name), name))
        bounded_fields = (
            "statistical_use_authority_artifact_sha256",
            "statistical_use_authority_record_hash",
            "inference_profile_id",
            "mean_zero_p_upper",
        )
        bounded_present = tuple(getattr(self, name) is not None for name in bounded_fields)
        if any(bounded_present):
            if (
                not all(bounded_present)
                or not all(projection_present)
                or type(self.inference_profile_id) is not str
                or self.inference_profile_id != BOUNDED_MEAN_PROFILE_ID
                or self.adjusted_p_value is not None
                or type(self.mean_zero_p_upper) not in (int, float)
                or type(self.sample_size) is not int
                or not 1 <= self.sample_size <= MAX_BOUNDED_MEAN_UNITS
            ):
                raise ScientificPromotionError(
                    "bounded-mean assessment requires one exact new inference source profile"
                )
            for name in bounded_fields[:2]:
                object.__setattr__(self, name, _sha256(getattr(self, name), name))
            object.__setattr__(self, "mean_zero_p_upper", _probability(
                self.mean_zero_p_upper, "mean_zero_p_upper", allow_zero=False,
            ))
        _enum(self, "metric_unit", MetricUnit)
        _enum(self, "metric_scope", MetricScope)
        for name in (
            "candidate_value",
            "baseline_value",
            "improvement_effect",
            "confidence_low",
            "confidence_high",
        ):
            object.__setattr__(self, name, _finite(getattr(self, name), name))
        if self.confidence_low > self.confidence_high:
            raise ScientificDesignError(
                "checked result-assessment confidence bounds are reversed"
            )
        if self.adjusted_p_value is not None:
            object.__setattr__(
                self,
                "adjusted_p_value",
                _probability(
                    self.adjusted_p_value,
                    "adjusted_p_value",
                    allow_zero=True,
                ),
            )
        _positive_int(self.sample_size, "sample_size")
        _enum(self, "hypothesis_status", HypothesisStatus)
        _enum(self, "outcome", ScientificResultOutcome)
        ScientificResultAssessmentDecision(
            outcome=self.outcome,
            hypothesis_status=self.hypothesis_status,
        )
        expected_eligibility = (
            self.outcome is not ScientificResultOutcome.TECHNICAL_FAILURE
        )
        if self.scientific_evidence_eligible is not expected_eligibility:
            raise ScientificPromotionError(
                "checked result scientific eligibility contradicts its outcome"
            )
        exclusions = tuple(
            _sha256(item, "baseline exclusion receipt SHA-256")
            for item in self.baseline_exclusion_receipt_sha256s
        )
        exclusion_records = tuple(
            _sha256(item, "baseline exclusion receipt record hash")
            for item in self.baseline_exclusion_receipt_record_hashes
        )
        if (
            len(exclusions) != len(exclusion_records)
            or len(set(exclusions)) != len(exclusions)
        ):
            raise ScientificPromotionError(
                "checked result baseline-exclusion closure is ambiguous"
            )
        object.__setattr__(self, "baseline_exclusion_receipt_sha256s", exclusions)
        object.__setattr__(
            self,
            "baseline_exclusion_receipt_record_hashes",
            exclusion_records,
        )
        if len(set(self.source_artifact_hashes)) != len(
            self.source_artifact_hashes
        ):
            raise ScientificPromotionError(
                "checked result-assessment source artifacts are aliased"
            )

    @property
    def source_artifact_hashes(self) -> tuple[str, ...]:
        if self.is_projection_backed:
            assert (
                self.generic_ml_paired_metric_projection_authority_artifact_sha256
                is not None
            )
            assert (
                self.scientific_execution_admissibility_authority_artifact_sha256
                is not None
            )
            assert self.domain_validity_receipt_artifact_sha256 is not None
            return (
                self.contract_artifact_sha256,
                self.scientific_execution_authority_artifact_sha256,
                self.generic_ml_paired_metric_projection_authority_artifact_sha256,
                self.scientific_execution_admissibility_authority_artifact_sha256,
                self.domain_validity_receipt_artifact_sha256,
                *((self.statistical_use_authority_artifact_sha256,)
                  if self.is_bounded_mean else ()),
                self.aggregate_result_sha256,
                self.statistical_analysis_sha256,
                *self.baseline_exclusion_receipt_sha256s,
            )
        assert self.evaluator_assessment_sha256 is not None
        assert self.scientific_obligations_sha256 is not None
        return (
            self.contract_artifact_sha256,
            self.scientific_execution_authority_artifact_sha256,
            self.aggregate_result_sha256,
            self.statistical_analysis_sha256,
            self.evaluator_assessment_sha256,
            self.scientific_obligations_sha256,
            *self.baseline_exclusion_receipt_sha256s,
        )

    @property
    def is_projection_backed(self) -> bool:
        return (
            self.generic_ml_paired_metric_projection_authority_artifact_sha256
            is not None
        )

    @property
    def is_bounded_mean(self) -> bool:
        return self.statistical_use_authority_artifact_sha256 is not None

    def to_dict(self) -> dict[str, Any]:
        result = {field.name: getattr(self, field.name) for field in fields(self)}
        if self.is_projection_backed:
            result["schema_version"] = (
                CHECKED_RESULT_ASSESSMENT_SCHEMA_V3 if self.is_bounded_mean
                else CHECKED_RESULT_ASSESSMENT_SCHEMA_V2
            )
            for name in (
                "evaluator_assessment_sha256",
                "evaluator_record_hash",
                "scientific_obligations_sha256",
                "obligations_record_hash",
            ):
                result.pop(name)
        else:
            result["schema_version"] = CHECKED_RESULT_ASSESSMENT_SCHEMA
            for name in (
                "generic_ml_paired_metric_projection_authority_artifact_sha256",
                "generic_ml_paired_metric_projection_authority_record_hash",
                "scientific_execution_admissibility_authority_artifact_sha256",
                "scientific_execution_admissibility_authority_record_hash",
                "domain_validity_receipt_artifact_sha256",
                "domain_validity_receipt_record_hash",
            ):
                result.pop(name)
        if self.is_bounded_mean:
            result.pop("adjusted_p_value")
        else:
            for name in (
                "statistical_use_authority_artifact_sha256",
                "statistical_use_authority_record_hash",
                "inference_profile_id", "mean_zero_p_upper",
            ):
                result.pop(name)
        result["metric_unit"] = self.metric_unit.value
        result["metric_scope"] = self.metric_scope.value
        result["hypothesis_status"] = self.hypothesis_status.value
        result["outcome"] = self.outcome.value
        result["baseline_exclusion_receipt_sha256s"] = list(
            self.baseline_exclusion_receipt_sha256s
        )
        result["baseline_exclusion_receipt_record_hashes"] = list(
            self.baseline_exclusion_receipt_record_hashes
        )
        return result

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> CheckedResultAssessment:
        schema = value.get("schema_version") if isinstance(value, Mapping) else None
        legacy_fields = {
            "evaluator_assessment_sha256",
            "evaluator_record_hash",
            "scientific_obligations_sha256",
            "obligations_record_hash",
        }
        projection_fields = {
            "generic_ml_paired_metric_projection_authority_artifact_sha256",
            "generic_ml_paired_metric_projection_authority_record_hash",
            "scientific_execution_admissibility_authority_artifact_sha256",
            "scientific_execution_admissibility_authority_record_hash",
            "domain_validity_receipt_artifact_sha256",
            "domain_validity_receipt_record_hash",
        }
        bounded_fields = {
            "statistical_use_authority_artifact_sha256",
            "statistical_use_authority_record_hash",
            "inference_profile_id", "mean_zero_p_upper",
        }
        common_fields = (set(cls.__dataclass_fields__) - legacy_fields
                         - projection_fields - bounded_fields)
        if schema == CHECKED_RESULT_ASSESSMENT_SCHEMA:
            expected_fields = common_fields | legacy_fields | {"schema_version"}
        elif schema == CHECKED_RESULT_ASSESSMENT_SCHEMA_V2:
            expected_fields = common_fields | projection_fields | {"schema_version"}
        elif schema == CHECKED_RESULT_ASSESSMENT_SCHEMA_V3:
            expected_fields = ((common_fields - {"adjusted_p_value"})
                               | projection_fields | bounded_fields | {"schema_version"})
        else:
            raise ScientificPromotionError(
                "unsupported checked result-assessment schema"
            )
        _require_exact_keys(
            value,
            expected_fields,
            "checked result assessment",
        )
        if schema == CHECKED_RESULT_ASSESSMENT_SCHEMA_V3 and any(
            value[name] is None for name in bounded_fields
        ):
            raise ScientificPromotionError(
                "bounded-mean assessment inference source fields cannot be null"
            )
        try:
            arguments = {
                name: value[name]
                for name in common_fields
                if name != "adjusted_p_value" or schema != CHECKED_RESULT_ASSESSMENT_SCHEMA_V3
            }
            if schema == CHECKED_RESULT_ASSESSMENT_SCHEMA_V3:
                arguments.update({name: value[name] for name in bounded_fields})
                arguments["adjusted_p_value"] = None
            if schema == CHECKED_RESULT_ASSESSMENT_SCHEMA:
                arguments.update({name: value[name] for name in legacy_fields})
                arguments.update({name: None for name in projection_fields})
            else:
                arguments.update({name: None for name in legacy_fields})
                arguments.update({name: value[name] for name in projection_fields})
            arguments["metric_unit"] = MetricUnit(arguments["metric_unit"])
            arguments["metric_scope"] = MetricScope(arguments["metric_scope"])
            arguments["hypothesis_status"] = HypothesisStatus(
                arguments["hypothesis_status"]
            )
            arguments["outcome"] = ScientificResultOutcome(arguments["outcome"])
            arguments["baseline_exclusion_receipt_sha256s"] = tuple(
                arguments["baseline_exclusion_receipt_sha256s"]
            )
            arguments["baseline_exclusion_receipt_record_hashes"] = tuple(
                arguments["baseline_exclusion_receipt_record_hashes"]
            )
            return cls(**arguments)
        except (KeyError, TypeError, ValueError) as exc:
            raise ScientificPromotionError(
                "checked result assessment is malformed"
            ) from exc


