@dataclass(frozen=True, slots=True)
class CheckedSuperiorityPromotionV2:
    """Optional positive-only consequence of an outcome-neutral assessment."""

    receipt_id: str
    checked_result_assessment_artifact_sha256: str
    checked_result_assessment_record_hash: str
    scientific_execution_authority_artifact_sha256: str
    scientific_execution_authority_record_hash: str
    improvement_effect: float
    confidence_low: float
    confidence_high: float
    adjusted_p_value: float
    sample_size: int
    scientific_evidence_eligible: bool = True
    status: SuperiorityValidationStatus = (
        SuperiorityValidationStatus.SCIENTIFIC_PROMOTION_AUTHORIZED
    )

    def __post_init__(self) -> None:
        object.__setattr__(self, "receipt_id", _identifier(self.receipt_id, "receipt_id"))
        for name in (
            "checked_result_assessment_artifact_sha256",
            "checked_result_assessment_record_hash",
            "scientific_execution_authority_artifact_sha256",
            "scientific_execution_authority_record_hash",
        ):
            object.__setattr__(self, name, _sha256(getattr(self, name), name))
        for name in (
            "improvement_effect",
            "confidence_low",
            "confidence_high",
            "adjusted_p_value",
        ):
            object.__setattr__(self, name, _finite(getattr(self, name), name))
        if (
            self.improvement_effect <= 0.0
            or self.confidence_low <= 0.0
            or self.confidence_low > self.confidence_high
            or not 0.0 <= self.adjusted_p_value <= 1.0
        ):
            raise ScientificPromotionError(
                "checked superiority v2 requires decisive positive evidence"
            )
        _positive_int(self.sample_size, "sample_size")
        if self.scientific_evidence_eligible is not True:
            raise ScientificPromotionError(
                "checked superiority v2 requires scientific evidence"
            )
        _enum(self, "status", SuperiorityValidationStatus)
        if self.status is not SuperiorityValidationStatus.SCIENTIFIC_PROMOTION_AUTHORIZED:
            raise ScientificPromotionError("checked superiority v2 is not authorized")

    @property
    def source_artifact_hashes(self) -> tuple[str, ...]:
        return (
            self.checked_result_assessment_artifact_sha256,
            self.scientific_execution_authority_artifact_sha256,
        )

    def to_dict(self) -> dict[str, Any]:
        result = {field.name: getattr(self, field.name) for field in fields(self)}
        result["schema_version"] = CHECKED_SUPERIORITY_RECEIPT_SCHEMA_V2
        result["status"] = self.status.value
        return result

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> CheckedSuperiorityPromotionV2:
        _require_exact_keys(
            value,
            set(cls.__dataclass_fields__) | {"schema_version"},
            "checked superiority v2 receipt",
        )
        if value["schema_version"] != CHECKED_SUPERIORITY_RECEIPT_SCHEMA_V2:
            raise ScientificPromotionError(
                "unsupported checked superiority v2 receipt schema"
            )
        try:
            arguments = {name: value[name] for name in cls.__dataclass_fields__}
            arguments["status"] = SuperiorityValidationStatus(arguments["status"])
            return cls(**arguments)
        except (KeyError, TypeError, ValueError) as exc:
            raise ScientificPromotionError(
                "checked superiority v2 receipt is malformed"
            ) from exc


@dataclass(frozen=True, slots=True)
class CheckedSuperiorityPromotionV3:
    """Inert closed receipt; only its complete source owner grants authority.

    This consequence establishes positive conditional mean improvement, not
    a meaningful population margin, seed generalization or resource advantage.
    """

    receipt_id: str
    checked_result_assessment_artifact_sha256: str
    checked_result_assessment_record_hash: str
    scientific_execution_authority_artifact_sha256: str
    scientific_execution_authority_record_hash: str
    contract_artifact_sha256: str
    contract_record_hash: str
    statistical_use_authority_artifact_sha256: str
    statistical_use_authority_record_hash: str
    frozen_policy_sha256: str
    improvement_effect: float
    confidence_low: float
    confidence_high: float
    mean_zero_p_upper: float
    sample_size: int
    inference_profile_id: str = BOUNDED_MEAN_PROFILE_ID
    claim_scope: str = BOUNDED_MEAN_SUPERIORITY_CLAIM_SCOPE
    conditional_scope: str = BOUNDED_MEAN_CONDITIONAL_SCOPE
    scientific_evidence_eligible: bool = True
    status: SuperiorityValidationStatus = SuperiorityValidationStatus.SCIENTIFIC_PROMOTION_AUTHORIZED

    def __post_init__(self) -> None:
        for name in (
            "receipt_id", "checked_result_assessment_artifact_sha256",
            "checked_result_assessment_record_hash", "scientific_execution_authority_artifact_sha256",
            "scientific_execution_authority_record_hash", "contract_artifact_sha256",
            "contract_record_hash", "statistical_use_authority_artifact_sha256",
            "statistical_use_authority_record_hash", "frozen_policy_sha256",
            "inference_profile_id", "claim_scope", "conditional_scope",
        ):
            if type(getattr(self, name)) is not str:
                raise ScientificPromotionError("bounded superiority identities must be native text")
        object.__setattr__(self, "receipt_id", _identifier(self.receipt_id, "receipt_id"))
        for name in (
            "checked_result_assessment_artifact_sha256", "checked_result_assessment_record_hash",
            "scientific_execution_authority_artifact_sha256", "scientific_execution_authority_record_hash",
            "contract_artifact_sha256", "contract_record_hash", "statistical_use_authority_artifact_sha256",
            "statistical_use_authority_record_hash", "frozen_policy_sha256",
        ):
            object.__setattr__(self, name, _sha256(getattr(self, name), name))
        for name in ("improvement_effect", "confidence_low", "confidence_high", "mean_zero_p_upper"):
            value = getattr(self, name)
            if type(value) not in (int, float):
                raise ScientificPromotionError("bounded superiority facts must be native finite numbers")
            try:
                valid = math.isfinite(value)
            except OverflowError:
                valid = False
            if not valid:
                raise ScientificPromotionError("bounded superiority facts must be finite")
            object.__setattr__(self, name, float(value))
        if (
            not 0 < self.confidence_low <= self.improvement_effect <= self.confidence_high <= 1
            or not 0 < self.mean_zero_p_upper <= 1
            or type(self.sample_size) is not int or not 1 <= self.sample_size <= MAX_BOUNDED_MEAN_UNITS
            or self.inference_profile_id != BOUNDED_MEAN_PROFILE_ID
            or self.claim_scope != BOUNDED_MEAN_SUPERIORITY_CLAIM_SCOPE
            or self.conditional_scope != BOUNDED_MEAN_CONDITIONAL_SCOPE
            or self.scientific_evidence_eligible is not True
            or type(self.status) not in (str, SuperiorityValidationStatus)
        ):
            raise ScientificPromotionError("bounded superiority exceeds its exact positive conditional scope")
        _enum(self, "status", SuperiorityValidationStatus)
        if self.status is not SuperiorityValidationStatus.SCIENTIFIC_PROMOTION_AUTHORIZED:
            raise ScientificPromotionError("bounded superiority is not authorized")
        if len(set(self.source_artifact_hashes)) != 4:
            raise ScientificPromotionError("bounded superiority source identities are aliased")

    @property
    def source_artifact_hashes(self) -> tuple[str, ...]:
        return (
            self.checked_result_assessment_artifact_sha256,
            self.scientific_execution_authority_artifact_sha256,
            self.contract_artifact_sha256,
            self.statistical_use_authority_artifact_sha256,
        )

    def to_dict(self) -> dict[str, Any]:
        return {"schema_version": CHECKED_SUPERIORITY_RECEIPT_SCHEMA_V3,
                **{item.name: getattr(self, item.name) for item in fields(self)},
                "status": self.status.value}

    @classmethod
    def from_dict(cls, value: Mapping[str, Any]) -> CheckedSuperiorityPromotionV3:
        _require_exact_keys(value, set(cls.__dataclass_fields__) | {"schema_version"}, "bounded superiority")
        if type(value["schema_version"]) is not str or value["schema_version"] != CHECKED_SUPERIORITY_RECEIPT_SCHEMA_V3:
            raise ScientificPromotionError("unsupported bounded superiority schema")
        try:
            return cls(**{name: value[name] for name in cls.__dataclass_fields__})
        except (KeyError, TypeError, ValueError) as exc:
            raise ScientificPromotionError("bounded superiority receipt is malformed") from exc


