        creator_role=Role.SCIENTIFIC_REVIEWER,
        creation_command=("scientist-one", "verify-baseline-exclusion"),
        parent_artifacts=tuple(item.sha256 for item in records),
        schema_version="1.0",
        mime_type="application/json",
        validation_result="PASS",
        frozen=True,
